(1, 'CQ100820', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100820\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"13\",\r\n    \"name\" : \"Create executable Java applications with a main method; run a Java program from the command line, including console output\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following method signatures is a valid declaration of an entry point in a Java application?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"public void main(String[] args)\"\r\n  }, {\r\n    \"respoonse\" : \"public static void main()\"\r\n  }, {\r\n    \"respoonse\" : \"private static void start(String[] mydata)\"\r\n  }, {\r\n    \"respoonse\" : \"public static final void main(String[] mydata)\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(2, 'CQ100159', '{\r\n  \"format\" : \"TEXT_UP_IMG_RASPUNSURI\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100159\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"15\",\r\n    \"name\" : \"Compare and contrast the features and components of Java, such as platform independence, object orientation, encapsulation, and so on\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"The following class diagram demonstrates the relationship between Gold and Silver, which extend the Metal class. Assume the attributes are all declared public. \\nWhich  statement about the diagram is not true?\",\r\n    \"img\" : \"D:\\\\LICENTA\\\\AdminApp\\\\src\\\\main\\\\resources\\\\images\\\\c12.png\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The diagram demonstrates platform independence in Java.\"\r\n  }, {\r\n    \"respoonse\" : \"The diagram demonstrates object-oriented design in Java.\"\r\n  }, {\r\n    \"respoonse\" : \"The Gold and Silver classes inherit weight and color attributes from the Metal class.\"\r\n  }, {\r\n    \"respoonse\" : \"Gold does not inherit the luster attribute\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(3, 'CQ100807', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100807\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"13\",\r\n    \"name\" : \"Create executable Java applications with a main method; run a Java program from the command line, including console output\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the proper filename extension for a Java bytecode compiled file?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \".java\"\r\n  }, {\r\n    \"respoonse\" : \".bytecode\"\r\n  }, {\r\n    \"respoonse\" : \".class\"\r\n  }, {\r\n    \"respoonse\" : \".dll\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(4, 'CQ100209', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100209\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"14\",\r\n    \"name\" : \"Import other Java packages to make them accessible in your code\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given that a Date class exists in both the java.util and java.sql packages, what is the result of compiling the following class?\",\r\n    \"code\" : \"1: import java.util.*; \\n2: import java.sql.*; \\n3: public class BirthdayManager { \\n4:    private Date rob = new Date(); \\n5:    private java.util.Date sharon = new java.util.Date(); \\n6: }\\n\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile because of lines 1 and 2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line 4.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line 5.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles without issue.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(5, 'CQ100515', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100515\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"15\",\r\n    \"name\" : \"Compare and contrast the features and components of Java, such as platform independence, object orientation, encapsulation, and so on\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is not a facet of traditional object-oriented programming languages?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Objects are grouped as procedures, separate from the data they act on.\"\r\n  }, {\r\n    \"respoonse\" : \"An object can take many forms via casting.\"\r\n  }, {\r\n    \"respoonse\" : \"An object can hold data, referred to as attributes.\"\r\n  }, {\r\n    \"respoonse\" : \"An object can perform actions, via methods.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(6, 'CQ100999', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100999\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"11\",\r\n    \"name\" : \"Define the scope of variables\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which variables have a scope limited to a method?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Interface variables\"\r\n  }, {\r\n    \"respoonse\" : \"Class variables\"\r\n  }, {\r\n    \"respoonse\" : \"Instance variables\"\r\n  }, {\r\n    \"respoonse\" : \"Local variables\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(7, 'CQ100920', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100920\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"14\",\r\n    \"name\" : \"Import other Java packages to make them accessible in your code\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \" Which package is imported into every Java class by default?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"java.util\"\r\n  }, {\r\n    \"respoonse\" : \"java.lang\"\r\n  }, {\r\n    \"respoonse\" : \"system.lang\"\r\n  }, {\r\n    \"respoonse\" : \"java.system\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(8, 'CQ100383', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100383\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"12\",\r\n    \"name\" : \"Define the structure of Java Class\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is not a valid code comment in Java?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"// Add 5 to the result\"\r\n  }, {\r\n    \"respoonse\" : \"/*** TODO: Fix bug 12312 ***/\"\r\n  }, {\r\n    \"respoonse\" : \"# Add configuration value\"\r\n  }, {\r\n    \"respoonse\" : \"/* Read file from system ****/\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(9, 'CQ100290', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100290\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"12\",\r\n    \"name\" : \"Define the structure of Java Class\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about a valid .java file is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"It can only contain one class declaration.\"\r\n  }, {\r\n    \"respoonse\" : \"It can contain one public class declaration and one public interface definition.\"\r\n  }, {\r\n    \"respoonse\" : \"It must define at least one public class.\"\r\n  }, {\r\n    \"respoonse\" : \"It may define at most one public class.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(10, 'CQ100220', '{\r\n  \"format\" : \"TEXT_UP_CODE_IMG_TEXT_DOWN_RESPONSES\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100220\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"11\",\r\n    \"name\" : \"Define the scope of variables\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following application, fill in the missing values in the table starting from the top and going downward.\",\r\n    \"code\" : \"package competition; \\npublic class Robot {   \\n\\tstatic String weight = \\\"A lot\\\";   \\n\\t/* default */ double ageMonths = 5, ageDays = 2;\\n\\tprivate static boolean success = true;   \\n\\tpublic void main(String[] args) {      \\n\\t\\tfinal String retries = \\\"1\\\";      // P1   \\n\\t} \\n}\",\r\n    \"img\" : \"D:\\\\LICENTA\\\\AdminApp\\\\src\\\\main\\\\resources\\\\images\\\\c110.png\",\r\n    \"textDown\" : \"\\nSelect the answer\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2, 0, 1\"\r\n  }, {\r\n    \"respoonse\" : \"2, 2, 1\"\r\n  }, {\r\n    \"respoonse\" : \"1, 0, 1\"\r\n  }, {\r\n    \"respoonse\" : \"0, 2, 1\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(11, 'CQ100907', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100907\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"13\",\r\n    \"name\" : \"Create executable Java applications with a main method; run a Java program from the command line, including console output\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about import statements is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The class will not compile if it contains unused import statements.\"\r\n  }, {\r\n    \"respoonse\" : \"Unused import statements can be removed from the class without causing a class to become unable to be compiled.\"\r\n  }, {\r\n    \"respoonse\" : \"The class will not compile if a duplicate import statement is present.\"\r\n  }, {\r\n    \"respoonse\" : \"If a class contains an import statement for a class used in the program that cannot be found, it can still compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(12, 'CQ100961', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100961\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"11\",\r\n    \"name\" : \"Define the scope of variables\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of compiling and executing the following class?\",\r\n    \"code\" : \"1: public class ParkRanger { \\n2:    int birds = 10; \\n3:    public static void main(String[] data) { \\n4:       int trees = 5; \\n5:       System.out.print(trees+birds); \\n6:    } \\n7: }\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"It does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"It compiles but throws an exception at runtime.\"\r\n  }, {\r\n    \"respoonse\" : \"It compiles and outputs 5.\"\r\n  }, {\r\n    \"respoonse\" : \"It compiles and outputs 15.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
