(40, 'CQ100389', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100389\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"14\",\r\n    \"name\" : \"Import other Java packages to make them accessible in your code\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given that a Math class exists in both the java.lang and pocket.complex packages, what\\nis the result of compiling the following class?\",\r\n    \"code\" : \"1: package pocket;\\n2: import pocket.complex.*;\\n3: import java.util.*;\\n4: public class Calculator {\\n5: \\tpublic static void main(String[] args) {\\n6: \\t\\tSystem.out.print(Math.floor(5));\\n7: \\t}\\n8: }\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile because of line 2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line 3.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line 6.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles without issue.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java');
