(41, 'CQ100136', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100136\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"14\",\r\n    \"name\" : \"Import other Java packages to make them accessible in your code\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given a class that uses the following import statements, which class would not be automatically\\naccessible within the class without using its full package name?\",\r\n    \"code\" : \"import dog.*;\\nimport dog.puppy.*;\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"dog.puppy.female.KC\"\r\n  }, {\r\n    \"respoonse\" : \"dog.puppy.Georgette\"\r\n  }, {\r\n    \"respoonse\" : \"dog.Webby\"\r\n  }, {\r\n    \"respoonse\" : \"java.lang.Object\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
