(43, 'CQ100275', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100275\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"14\",\r\n    \"name\" : \"Import other Java packages to make them accessible in your code\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following class definition, what is the maximum number of import statements\\nthat can be discarded and still have the code compile? For this question, assume that the\\nBroccoli class is in the food.vegetables package, and the Apple class is the food.fruit\\npackage.\",\r\n    \"code\" : \"package food;\\nimport food.vegetables.*;\\nimport food.fruit.*;\\nimport java.util.Date;\\n\\npublic class Grocery {\\n\\tApple a; Broccoli b; Date c;\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"0\"\r\n  }, {\r\n    \"respoonse\" : \"1\"\r\n  }, {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"3\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(44, 'CQ100549', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ100549\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"11\",\r\n    \"name\" : \"Define the scope of variables\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following application, what is the expected output?\",\r\n    \"code\" : \"public class Keyboard {\\n\\tprivate boolean numLock = true;\\n\\tstatic boolean capLock = false;\\n\\tpublic static void main(String... shortcuts) {\\n\\t\\tSystem.out.print(numLock+\\\" \\\"+capLock);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"true false\"\r\n  }, {\r\n    \"respoonse\" : \"false false\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"It compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(45, 'CQ100459', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ100459\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"11\",\r\n    \"name\" : \"Define the scope of variables\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of compiling and executing the following class?\",\r\n    \"code\" : \"public class RollerSkates {\\n\\tstatic int wheels = 1;\\n\\tint tracks = 5;\\n\\tpublic static void main(String[] arguments) {\\n\\t\\tRollerSkates s = new RollerSkates();\\n\\t\\tint feet=4, tracks = 15;\\n\\t\\tSystem.out.print(feet + tracks + s.wheels);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"5\"\r\n  }, {\r\n    \"respoonse\" : \"10\"\r\n  }, {\r\n    \"respoonse\" : \"20\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(46, 'CQ100418', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ100418\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"13\",\r\n    \"name\" : \"Create executable Java applications with a main method; run a Java program from the command line, including console output\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of compiling and executing the following class?\",\r\n    \"code\" : \"package sports;\\npublic class Bicycle {\\n\\tString color = \\\"red\\\";\\n\\tprivate void printColor(String color) {\\n\\t\\tcolor = \\\"purple\\\";\\n\\t\\tSystem.out.print(color);\\n\\t}\\n\\tpublic static void main(String[] rider) {\\n\\t\\tnew Bicycle().printColor(\\\"blue\\\");\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"red\"\r\n  }, {\r\n    \"respoonse\" : \"purple\"\r\n  }, {\r\n    \"respoonse\" : \"blue\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(47, 'CQ100997', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ100997\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"13\",\r\n    \"name\" : \"Create executable Java applications with a main method; run a Java program from the command line, including console output\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statements about calling the compilation command javac and the execution command\\njava are true?\\n\\tI. java may use a period . to separate packages.\\n\\tII. javac takes a .java file and returns a .class file.\\n\\tIII. java may use a slash (/) to separate packages.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I only\"\r\n  }, {\r\n    \"respoonse\" : \"II only\"\r\n  }, {\r\n    \"respoonse\" : \"I and II\"\r\n  }, {\r\n    \"respoonse\" : \"I, II, and III\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
