(50, 'CQ100946', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ100946\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"1\",\r\n    \"name\" : \"Java Basics\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"13\",\r\n    \"name\" : \"Create executable Java applications with a main method; run a Java program from the command line, including console output\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about the JVM is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The JVM schedules garbage collection on a predictable schedule.\"\r\n  }, {\r\n    \"respoonse\" : \"The JVM ensures that the application will always terminate.\"\r\n  }, {\r\n    \"respoonse\" : \"The JVM requires a properly defined entry point method to execute the application.\"\r\n  }, {\r\n    \"respoonse\" : \"A Java compiled code can be run on any computer.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
