(69, 'CQ200147', '{\r\n  \"format\" : \"TEXT_UP_CODE_IMG_TEXT_DOWN_RESPONSES\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ200147\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"24\",\r\n    \"name\" : \"Explain an Object’s Lifecycle (creation, “dereference by reassignment” and garbage collection)\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Suppose you have the following code. Which of the images best represents the state of the\\nreferences right before the end of the main method, assuming garbage collection hasn’t run?\",\r\n    \"code\" : \"1: public class Link {\\n2: \\tprivate String name;\\n3: \\tprivate Link next;\\n4: \\tpublic Link(String name, Link next) {\\n5:\\t\\t this.name = name;\\n6:\\t\\t this.next = next;\\n7: \\t}\\n8: \\tpublic void setNext(Link next) {\\n9: \\t\\tthis.next = next;\\n10:\\t }\\n11: \\tpublic Link getNext() {\\n12: \\t\\treturn next;\\n13: \\t}\\n14: \\tpublic static void main(String... args) {\\n15:\\t\\tLink link1 = new Link(\\\"x\\\", null);\\n16: \\t\\tLink link2 = new Link(\\\"y\\\", link1);\\n17: \\t\\tLink link3 = new Link(\\\"z\\\", link2);\\n18:\\t\\tlink2.setNext(link3);\\n19:\\t\\tlink3.setNext(link2);\\n20: \\t\\tlink1 = null;\\n21: \\t\\tlink3 = null;\\n22: \\t}\\n23: }\",\r\n    \"img\" : \"D:\\\\LICENTA\\\\AdminApp\\\\src\\\\main\\\\resources\\\\images\\\\c219.png\",\r\n    \"textDown\" : \"Select\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Option A\"\r\n  }, {\r\n    \"respoonse\" : \"Option B\"\r\n  }, {\r\n    \"respoonse\" : \"Option C\"\r\n  }, {\r\n    \"respoonse\" : \"Option D\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(70, 'CQ200990', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ200990\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"21\",\r\n    \"name\" : \"Declare and initialize variables (including casting of primitive data types)\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which type can fill in the blank?\",\r\n    \"code\" : \"___________ pi = 3.14;\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"byte\"\r\n  }, {\r\n    \"respoonse\" : \"float\"\r\n  }, {\r\n    \"respoonse\" : \"double\"\r\n  }, {\r\n    \"respoonse\" : \"short\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(71, 'CQ200342', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ200342\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"21\",\r\n    \"name\" : \"Declare and initialize variables (including casting of primitive data types)\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the first line in the following code to not compile?\",\r\n    \"code\" : \"public static void main(String[] args) {\\n\\tint Integer = 0; // k1\\n\\tInteger int = 0; // k2\\n\\tInteger ++; // k3\\n\\tint++; // k4\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"k1\"\r\n  }, {\r\n    \"respoonse\" : \"k2\"\r\n  }, {\r\n    \"respoonse\" : \"k3\"\r\n  }, {\r\n    \"respoonse\" : \"k4\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(72, 'CQ200813', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ200813\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"23\",\r\n    \"name\" : \"Know how to read or write to object fields\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Suppose foo is a reference to an instance of a class. Which of the following is not true\\nabout foo.bar?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"bar is an instance variable.\"\r\n  }, {\r\n    \"respoonse\" : \"bar is a local variable.\"\r\n  }, {\r\n    \"respoonse\" : \"It can be used to read from bar.\"\r\n  }, {\r\n    \"respoonse\" : \"It can be used to write to bar.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(73, 'CQ200549', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ200549\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"21\",\r\n    \"name\" : \"Declare and initialize variables (including casting of primitive data types)\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is not a valid class declaration?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"class building {}\"\r\n  }, {\r\n    \"respoonse\" : \"class Cost$ {}\"\r\n  }, {\r\n    \"respoonse\" : \"class 5MainSt {}\"\r\n  }, {\r\n    \"respoonse\" : \"class _Outside {}\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(74, 'CQ200929', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ200929\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"21\",\r\n    \"name\" : \"Declare and initialize variables (including casting of primitive data types)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following can fill in the blanks to make this code compile?\",\r\n    \"code\" : \"_________________ d = new ______________________ (1_000_000_.00)\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"double, double\"\r\n  }, {\r\n    \"respoonse\" : \"double, Double\"\r\n  }, {\r\n    \"respoonse\" : \"Double, double\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(75, 'CQ200427', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ200427\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"21\",\r\n    \"name\" : \"Declare and initialize variables (including casting of primitive data types)\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which is correct about a local variable of type String?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"It defaults to an empty string.\"\r\n  }, {\r\n    \"respoonse\" : \"It defaults to null.\"\r\n  }, {\r\n    \"respoonse\" : \"It does not have a default value.\"\r\n  }, {\r\n    \"respoonse\" : \"It will not compile without initializing on the declaration line.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(76, 'CQ200431', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ200431\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"21\",\r\n    \"name\" : \"Declare and initialize variables (including casting of primitive data types)\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Of the types double, int, long, and short, how many could fill in the blank to have this\\ncode output 0?\",\r\n    \"code\" : \"static __________ defaultValue;\\n\\n\\tpublic static void main(String[] args) {\\n\\t\\tSystem.out.println(defaultValue);\\n\\t}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"Three\"\r\n  }, {\r\n    \"respoonse\" : \"Four\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(77, 'CQ200753', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ200753\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"22\",\r\n    \"name\" : \"Differentiate between object reference variables and primitive variables\"\r\n  }, {\r\n    \"id\" : \"25\",\r\n    \"name\" : \"Develop code that uses wrapper classes such as Boolean, Double, and Integer\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is true about primitives?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"You can call methods on a primitive.\"\r\n  }, {\r\n    \"respoonse\" : \"You can convert a primitive to a wrapper class object simply by assigning it.\"\r\n  }, {\r\n    \"respoonse\" : \"You can convert a wrapper class object to a primitive by calling valueOf().\"\r\n  }, {\r\n    \"respoonse\" : \"You can store a primitive directly into an ArrayList.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(78, 'CQ200784', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ200784\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"22\",\r\n    \"name\" : \"Differentiate between object reference variables and primitive variables\"\r\n  }, {\r\n    \"id\" : \"25\",\r\n    \"name\" : \"Develop code that uses wrapper classes such as Boolean, Double, and Integer\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"Integer integer = new Integer(4);\\nSystem.out.print(integer.byteValue());\\n\\nSystem.out.print(\\\"-\\\");\\n\\nint i = new Integer(4);\\nSystem.out.print(i.byteValue());\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"4-0\"\r\n  }, {\r\n    \"respoonse\" : \"4-4\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(79, 'CQ200225', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ200225\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"23\",\r\n    \"name\" : \"Know how to read or write to object fields\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following code, fill in the blank to have the code print bounce.\",\r\n    \"code\" : \"public class TennisBall {\\n\\tpublic TennisBall() {\\n\\t\\tSystem.out.println(\\\"bounce\\\");\\n\\t}\\n\\tpublic static void main(String[] slam) {\\n\\t\\t______________________\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"TennisBall;\"\r\n  }, {\r\n    \"respoonse\" : \"TennisBall();\"\r\n  }, {\r\n    \"respoonse\" : \"new TennisBall;\"\r\n  }, {\r\n    \"respoonse\" : \"new TennisBall();\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(80, 'CQ200950', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ200950\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"21\",\r\n    \"name\" : \"Declare and initialize variables (including casting of primitive data types)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following correctly assigns animal to both variables?\\n\\tI. String cat = \\\"animal\\\", dog = \\\"animal\\\";\\n\\tII. String cat = \\\"animal\\\"; dog = \\\"animal\\\";\\n\\tIII. String cat, dog = \\\"animal\\\";\\n\\tIV. String cat, String dog = \\\"animal\\\";\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I\"\r\n  }, {\r\n    \"respoonse\" : \"I, II\"\r\n  }, {\r\n    \"respoonse\" : \"I, III\"\r\n  }, {\r\n    \"respoonse\" : \"I, II, III, IV\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java');
