(85, 'CQ200455', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ200455\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"24\",\r\n    \"name\" : \"Explain an Object’s Lifecycle (creation, “dereference by reassignment” and garbage collection)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many of the String objects are eligible for garbage collection right before the end of\\nthe main method?\",\r\n    \"code\" : \"public static void main(String[] fruits) {\\n\\n\\tString fruit1 = new String(\\\"apple\\\");\\n\\tString fruit2 = new String(\\\"orange\\\");\\n\\tString fruit3 = new String(\\\"pear\\\");\\n\\n\\tfruit3 = fruit1;\\n\\tfruit2 = fruit3;\\n\\tfruit1 = fruit2;\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"None\"\r\n  }, {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"Three\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
