(94, 'CQ200931', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ200931\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"23\",\r\n    \"name\" : \"Know how to read or write to object fields\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which is the most common way to fill in the blank to implement this method?\",\r\n    \"code\" : \"public class Penguin {\\n\\tprivate double beakLength;\\n\\t\\tpublic static void setBeakLength(Penguin p, int b) {\\n\\t\\t\\t________________\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"p.beakLength = b;\"\r\n  }, {\r\n    \"respoonse\" : \"p[\'beakLength\'] = b;\"\r\n  }, {\r\n    \"respoonse\" : \"p[beakLength] = b;\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
