(96, 'CQ200764', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ200764\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"24\",\r\n    \"name\" : \"Explain an Object’s Lifecycle (creation, “dereference by reassignment” and garbage collection)\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many objects are eligible for garbage collection right before the end of the main\\nmethod?\",\r\n    \"code\" : \"1: public class Person {\\n2: \\tpublic Person youngestChild;\\n3:\\n4: \\tpublic static void main(String... args) {\\n5:\\t\\tPerson elena = new Person();\\n6: \\t\\tPerson diana = new Person();\\n7:\\t\\telena.youngestChild = diana;\\n8: \\t\\tdiana = null;\\n9: \\t\\tPerson zoe = new Person();\\n10: \\t\\telena.youngestChild = zoe;\\n11:\\t\\tzoe = null;\\n12: \\t}\\n13: }\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"None\"\r\n  }, {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"Three\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(97, 'CQ200933', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ200933\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"22\",\r\n    \"name\" : \"Differentiate between object reference variables and primitive variables\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which is a valid constructor for this class?\",\r\n    \"code\" : \"public class TennisBall {\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"public TennisBall static create() { return new TennisBall(); }\"\r\n  }, {\r\n    \"respoonse\" : \"public TennisBall static newInstance() { return new TennisBall():}\"\r\n  }, {\r\n    \"respoonse\" : \"public TennisBall() {}\"\r\n  }, {\r\n    \"respoonse\" : \"public void TennisBall() {}\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(98, 'CQ200818', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ200818\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"2\",\r\n    \"name\" : \"Working With Java Data Types\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"24\",\r\n    \"name\" : \"Explain an Object’s Lifecycle (creation, “dereference by reassignment” and garbage collection)\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is not a possible output of this code, assuming it runs to\\ncompletion?\",\r\n    \"code\" : \"package store;\\npublic class Toy {\\n\\tpublic void play() {\\n\\t\\tSystem.out.print(\\\"play-\\\");\\n\\t}\\n\\tpublic void finalize() {\\n\\t\\tSystem.out.print(\\\"clean-\\\");\\n\\t}\\n\\tpublic static void main(String[] args) {\\n\\t\\tToy car = new Toy();\\n\\t\\tcar.play();\\n\\t\\tSystem.gc();\\n\\t\\tToy doll = new Toy();\\n\\t\\tdoll.play();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"play-\"\r\n  }, {\r\n    \"respoonse\" : \"play-play-\"\r\n  }, {\r\n    \"respoonse\" : \"play-play-clean-\"\r\n  }, {\r\n    \"respoonse\" : \"play-play-clean-clean\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
