(108, 'CQ300164', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ300164\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"3\",\r\n    \"name\" : \"Using Operators and Decision Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"31\",\r\n    \"name\" : \"Use Java operators; use parentheses to override operator precedence\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about ternary expressions is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"In some cases, both expressions to the right of the conditional operator in a ternary expression will be evaluated at runtime.\"\r\n  }, {\r\n    \"respoonse\" : \"Ternary expressions require parentheses for proper evaluation.\"\r\n  }, {\r\n    \"respoonse\" : \"The ternary expressions are a convenient replacement for an if-then-else statement.\"\r\n  }, {\r\n    \"respoonse\" : \"Ternary expressions support int and boolean expressions for the left-most operand.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(109, 'CQ300140', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ300140\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"3\",\r\n    \"name\" : \"Using Operators and Decision Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"32\",\r\n    \"name\" : \"Test equality between Strings and other objects using == and equals()\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package voting;\\n1: public class Election {\\n2: \\tpublic void calculateResult(Integer candidateA, Integer candidateB) {\\n3: \\t\\tboolean process = candidateA == null || candidateA.intValue() < 10;\\n4:\\t\\tboolean value = candidateA && candidateB;\\n5: \\t\\tSystem.out.print(process || value);\\n6: \\t}\\n7: \\tpublic static void main(String[] unused) {\\n8: \\t\\tnew Election().calculateResult(null,203);\\n9: \\t}\\n10:}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"true\"\r\n  }, {\r\n    \"respoonse\" : \"false\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws a NullPointerException on line 3 at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(110, 'CQ300974', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ300974\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"3\",\r\n    \"name\" : \"Using Operators and Decision Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"34\",\r\n    \"name\" : \"Use a switch statement\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package restaurant;\\npublic class Pieces {\\n\\tpublic static void main(String[] info) {\\n\\t\\tint flair = 15;\\n\\t\\tif(flair >= 15 && flair < 37) {\\n\\t\\t\\tSystem.out.print(\\\"Not enough\\\");\\n\\t\\t} if(flair==37) {\\n\\t\\t\\tSystem.out.print(\\\"Just right\\\");\\n\\t\\t} else {\\n\\t\\t\\tSystem.out.print(\\\"Too many\\\");\\n\\t\\t}\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Not enough\"\r\n  }, {\r\n    \"respoonse\" : \"Just right\"\r\n  }, {\r\n    \"respoonse\" : \"Too many\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
