(116, 'CQ300679', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ300679\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"3\",\r\n    \"name\" : \"Using Operators and Decision Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"34\",\r\n    \"name\" : \"Use a switch statement\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: The ___________________ operator increases the value of a variable\\nby 1 and returns the new value, while the _______________ operator decreases the\\nvalue of a variable by 1 and returns the original value.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"pre-increment [++v], pre-decrement [--v]\"\r\n  }, {\r\n    \"respoonse\" : \"pre-increment [++v], post-decrement [v--]\"\r\n  }, {\r\n    \"respoonse\" : \"post-increment [v++], pre-decrement [--v]\"\r\n  }, {\r\n    \"respoonse\" : \"post-increment [v++], post-decrement [v--]\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
