(118, 'CQ300554', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ300554\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"3\",\r\n    \"name\" : \"Using Operators and Decision Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"31\",\r\n    \"name\" : \"Use Java operators; use parentheses to override operator precedence\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following code snippet, assuming dayOfWeek is an int, what variable type of\\nsaturday is not permitted?\",\r\n    \"code\" : \"final __________ saturday = 6;\\nswitch(dayOfWeek) {\\n\\tdefault:\\n\\t\\tSystem.out.print(\\\"Another Weekday\\\");\\n\\t\\tbreak;\\n\\tcase saturday:\\n\\t\\tSystem.out.print(\\\"Weekend!\\\");\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"byte\"\r\n  }, {\r\n    \"respoonse\" : \"long\"\r\n  }, {\r\n    \"respoonse\" : \"int\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
