(198, 'CQ400699', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ400699\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"4\",\r\n    \"name\" : \"Creating and Using Arrays\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"41\",\r\n    \"name\" : \"Declare, instantiate, initialize and use a one-dimensional array\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"I. You can always change a method signature from call(String[] arg) to\\ncall(String... arg) without causing a compiler error in the calling code.\\nII. You can always change a method signature from call(String... arg) to\\ncall(String[] arg) without causing a compiler error in the existing code.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I\"\r\n  }, {\r\n    \"respoonse\" : \"II\"\r\n  }, {\r\n    \"respoonse\" : \"Both I and II\"\r\n  }, {\r\n    \"respoonse\" : \"Neither I nor II\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java');
