(216, 'CQ500279', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ500279\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"51\",\r\n    \"name\" : \"Create and use while loops\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following code?\",\r\n    \"code\" : \"public class Loop {\\n\\tprivate static int count;\\n\\tprivate static String[] stops = new String[] { \\\"Washington\\\",\\n\\t\\t\\\"Monroe\\\", \\\"Jackson\\\", \\\"LaSalle\\\" };\\n\\tpublic static void main(String[] args) {\\n\\t\\twhile (count < stops.length) {\\n\\t\\t\\tif (stops[count++].length() < 8) {\\n\\t\\t\\t\\tbreak;\\n\\t\\t\\t}\\n\\t\\t}\\n\\t\\tSystem.out.println(count);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"1\"\r\n  }, {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"4\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(217, 'CQ500173', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500173\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"53\",\r\n    \"name\" : \"Create and use do/while loops\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of the following code?\",\r\n    \"code\" : \"do {\\n\\tint count = 0;\\n\\tdo {\\n\\t\\tcount++;\\n\\t} while (count < 2);\\n\\t\\tbreak;\\n} while (true);\\nSystem.out.println(count);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"3\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"This is an infinite loop.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
