(231, 'CQ500138', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500138\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"51\",\r\n    \"name\" : \"Create and use while loops\"\r\n  }, {\r\n    \"id\" : \"52\",\r\n    \"name\" : \"Create and use for loops including the enhanced for loop\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of the following?\",\r\n    \"code\" : \"int k = 0;\\nfor (int i = 10; i > 0; i--) {\\n\\twhile (i > 3) i -= 3;\\n\\tk += 1;\\n}\\nSystem.out.println(k);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"1\"\r\n  }, {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"3\"\r\n  }, {\r\n    \"respoonse\" : \"4\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(232, 'CQ500762', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ500762\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"52\",\r\n    \"name\" : \"Create and use for loops including the enhanced for loop\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is equivalent to this code snippet given an array of String objects?\",\r\n    \"code\" : \"for (int i=fun.length-1; i>=0; i--)\\n\\tSystem.out.println(fun[i]);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"for (String f = fun) System.out.println(f);\"\r\n  }, {\r\n    \"respoonse\" : \"for (String f : fun) System.out.println(f);\"\r\n  }, {\r\n    \"respoonse\" : \"for (String f fun) System.out.println(it);\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(233, 'CQ500821', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500821\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"52\",\r\n    \"name\" : \"Create and use for loops including the enhanced for loop\"\r\n  }, {\r\n    \"id\" : \"55\",\r\n    \"name\" : \"Use break and continue\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What does the following code output?\",\r\n    \"code\" : \"public static void main(String[] args) {\\n\\tList<String> bottles = Arrays.asList(\\\"glass\\\", \\\"plastic\\\");\\n\\tfor (int type = 0; type < bottles.size();)\\n\\t\\tSystem.out.print(bottles.get(type) + \\\",\\\");\\n\\t\\tbreak;\\n\\tSystem.out.print(\\\"end\\\");\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"glass,end\"\r\n  }, {\r\n    \"respoonse\" : \"glass,plastic,end\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(234, 'CQ500914', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ500914\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"52\",\r\n    \"name\" : \"Create and use for loops including the enhanced for loop\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of the following?\",\r\n    \"code\" : \"String[] nycTourLoops = new String[] { \\\"Downtown\\\", \\\"Uptown\\\", \\\"Brooklyn\\\" };\\nString[] times = new String[] { \\\"Day\\\", \\\"Night\\\" };\\nfor (int i = 0, j = 0; i < nycTourLoops.length\\n\\t&& j < times.length; i++; j++)\\n{\\n\\tSystem.out.print(nycTourLoops[i] + \\\" \\\" + times[j] + \\\"-\\\");\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Downtown Day-\"\r\n  }, {\r\n    \"respoonse\" : \"Downtown Day-Uptown Night-\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(235, 'CQ500502', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500502\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"52\",\r\n    \"name\" : \"Create and use for loops including the enhanced for loop\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of the following when run with\\njava peregrine.TimeLoop September 3 1940?\",\r\n    \"code\" : \"package peregrine;\\npublic class TimeLoop {\\n\\tpublic static void main(String[] args) {\\n\\t\\tfor (int i = args.length; i>=0; i--)\\n\\t\\t\\tSystem.out.println(args[i]);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"September\"\r\n  }, {\r\n    \"respoonse\" : \"1940\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(236, 'CQ500507', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500507\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"51\",\r\n    \"name\" : \"Create and use while loops\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"public class Shoelaces {\\n\\tpublic static void main(String[] args) {\\n\\t\\tString tie = null;\\n\\t\\twhile (tie == null)\\n\\t\\t\\ttie = \\\"shoelace\\\";\\n\\t\\t\\tSystem.out.print(tie);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"null\"\r\n  }, {\r\n    \"respoonse\" : \"shoelace\"\r\n  }, {\r\n    \"respoonse\" : \"shoelaceshoelace\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(237, 'CQ500256', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500256\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"53\",\r\n    \"name\" : \"Create and use do/while loops\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"The following code outputs a single letter x. What happens if you remove lines 25 and 28?\",\r\n    \"code\" : \"23: String race = \\\"\\\";\\n24: loop:\\n25: do {\\n26: \\trace += \\\"x\\\";\\n27:\\t break loop;\\n28: } while (true);\\n29: System.out.println(race);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"It prints an empty string.\"\r\n  }, {\r\n    \"respoonse\" : \"It still outputs a single letter x.\"\r\n  }, {\r\n    \"respoonse\" : \"It no longer compiles.\"\r\n  }, {\r\n    \"respoonse\" : \"It becomes an infinite loop.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(238, 'CQ500732', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ500732\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"51\",\r\n    \"name\" : \"Create and use while loops\"\r\n  }, {\r\n    \"id\" : \"55\",\r\n    \"name\" : \"Use break and continue\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following code?\",\r\n    \"code\" : \"package chicago;\\npublic class Loop {\\n\\tprivate static int count;\\n\\tprivate static String[] stops = new String[] { \\\"Washington\\\",\\n\\t\\t\\\"Monroe\\\", \\\"Jackson\\\", \\\"LaSalle\\\" };\\n\\tpublic static void main(String[] args) {\\n\\t\\twhile (count < stops.length) {\\n\\t\\t\\tif (stops[count++].length() < 8) {\\n\\t\\t\\t\\tcontinue;\\n\\t\\t\\t}\\n\\t\\t}\\n\\t\\tSystem.out.println(count);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"1\"\r\n  }, {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"4\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(239, 'CQ500184', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500184\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"53\",\r\n    \"name\" : \"Create and use do/while loops\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"StringBuilder builder = new StringBuilder();\\nString str = new String(\\\"Leaves growing\\\");\\ndo {\\n\\tSystem.out.println(str);\\n} while (builder);\\nSystem.out.println(builder);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Leaves growing\"\r\n  }, {\r\n    \"respoonse\" : \"This is an infinite loop.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java');
