(240, 'CQ500952', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ500952\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"53\",\r\n    \"name\" : \"Create and use do/while loops\"\r\n  }, {\r\n    \"id\" : \"55\",\r\n    \"name\" : \"Use break and continue\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of the following code?\",\r\n    \"code\" : \"6: int count = 0;\\n7: do {\\n8: \\tdo {\\n9:\\t\\t count++;\\n10: \\t} while (count < 2);\\n11:\\t break;\\n12: } while (true);\\n13: System.out.println(count);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"3\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"This is an infinite loop.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
