(243, 'CQ500906', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ500906\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"52\",\r\n    \"name\" : \"Create and use for loops including the enhanced for loop\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many lines does the following code output?\",\r\n    \"code\" : \"import java.util.*;\\npublic class Exams {\\n\\tpublic static void main(String[] args) {\\n\\t\\tList<String> exams = Arrays.asList(\\\"OCA\\\", \\\"OCP\\\");\\n\\t\\tfor (String e1 : exams)\\n\\t\\t\\tfor (String e2 : exams)\\n\\t\\t\\t\\tSystem.out.println(e1 + \\\" \\\" + e2);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Four\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
