(250, 'CQ500826', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ500826\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"5\",\r\n    \"name\" : \"Using Loop Constructs\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"52\",\r\n    \"name\" : \"Create and use for loops including the enhanced for loop\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following can fill in the blank to have the code compile successfully?\",\r\n    \"code\" : \"package nyc;\\npublic class TouristBus {\\n\\tpublic static void main(String... args) {\\n\\t\\tString[] nycTourLoops = new String[] { \\\"Downtown\\\", \\\"Uptown\\\", \\\"Brooklyn\\\" };\\n\\t\\tString[] times = new String[] { \\\"Day\\\", \\\"Night\\\" };\\n\\t\\t\\tfor (______________ i < 1; i++, j++)\\n\\t\\t\\t\\tSystem.out.println(nycTourLoops[i] + \\\" \\\" + times[j]);\\n}\\t\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"int i=0; j=0;\"\r\n  }, {\r\n    \"respoonse\" : \"int i=0, j=0;\"\r\n  }, {\r\n    \"respoonse\" : \"int i=0; int j=0;\"\r\n  }, {\r\n    \"respoonse\" : \"int i=0, int j=0;\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
