(260, 'CQ600104', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ600104\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"63\",\r\n    \"name\" : \"Create and overload constructors; differentiate between default and user defined constructors\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which line of code, inserted at line p1, causes the application to print 5?\",\r\n    \"code\" : \"package games;\\npublic class Jump {\\n\\tprivate int rope = 1;\\n\\tprotected boolean outside;\\n\\n\\tpublic Jump() {\\n\\t\\t// p1\\n\\t\\toutside = true;\\n\\t}\\n\\n\\tpublic Jump(int rope) {\\n\\t\\tthis.rope = outside ? rope : rope+1;\\n\\t}\\n\\n\\tpublic static void main(String[] bounce) {\\n\\t\\tSystem.out.print(new Jump().rope);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"this(4);\"\r\n  }, {\r\n    \"respoonse\" : \"new Jump(4);\"\r\n  }, {\r\n    \"respoonse\" : \"this(5);\"\r\n  }, {\r\n    \"respoonse\" : \"rope = 4;\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(261, 'CQ600393', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ600393\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"64\",\r\n    \"name\" : \"Apply access modifiers\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements is not true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"An instance of one class may access an instance of another class’s attributes if it has a reference to the instance and the attributes are declared public.\"\r\n  }, {\r\n    \"respoonse\" : \"An instance of one class may access package-private attributes in a parent class, provided the parent class is not in the same package.\"\r\n  }, {\r\n    \"respoonse\" : \"Two instances of the same class may access each other’s private attributes.\"\r\n  }, {\r\n    \"respoonse\" : \"An instance of one class may access an instance of another class’s attributes if both classes are located in the same package and marked protected.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(262, 'CQ600852', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600852\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"64\",\r\n    \"name\" : \"Apply access modifiers\"\r\n  }, {\r\n    \"id\" : \"65\",\r\n    \"name\" : \"Apply encapsulation principles to a class\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following class, what should be inserted into the two blanks to ensure the class\\ndata is properly encapsulated?\",\r\n    \"code\" : \"package storage;\\npublic class Box {\\n\\tpublic String stuff;\\n\\t______________ String  __________________() {\\n\\t\\treturn stuff;\\n\\t}\\n\\n\\tpublic void setStuff(String stuff) {\\n\\t\\tthis.stuff = stuff;\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"public and getStuff\"\r\n  }, {\r\n    \"respoonse\" : \"private and isStuff\"\r\n  }, {\r\n    \"respoonse\" : \"public and setStuff\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(263, 'CQ600849', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600849\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"63\",\r\n    \"name\" : \"Create and overload constructors; differentiate between default and user defined constructors\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about a no-argument constructor is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The Java compiler will always insert a default no-argument constructor if you do not define a no-argument constructor in your class.\"\r\n  }, {\r\n    \"respoonse\" : \"In order for a class to call super() in one of its constructors, its parent class must explicitly implement a no-argument constructor.\"\r\n  }, {\r\n    \"respoonse\" : \"If a class extends another class that has only one constructor that takes a value, then the child class must explicitly declare at least one constructor.\"\r\n  }, {\r\n    \"respoonse\" : \"A class may contain more than one no-argument constructor.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
