(265, 'CQ600742', '{\r\n  \"format\" : \"TEXT_UP_CODE_IMG_TEXT_DOWN_RESPONSES\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ600742\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"66\",\r\n    \"name\" : \"Determine the effect upon object references and primitive values when they are passed into methods that change the values\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following application, which diagram best represents the state of the mySkier,\\nmySpeed, and myName variables in the main() method after the call to the slalom()\\nmethod?\",\r\n    \"code\" : \"package slopes;\\npublic class Ski {\\n\\tprivate int age = 18;\\n\\tprivate static void slalom(Ski racer, int[] speed, String name) {\\n\\t\\tracer.age = 18;\\n\\t\\tname = \\\"Wendy\\\";\\n\\t\\tspeed = new int[1];\\n\\t\\tspeed[0] = 11;\\n\\t\\tracer = null;\\n\\t}\\n\\tpublic static void main(String... mountain) {\\n\\t\\tfinal Ski mySkier = new Ski();\\n\\t\\tmySkier.age = 16;\\n\\t\\tfinal int[] mySpeed = new int[1];\\n\\t\\tfinal String myName = \\\"Rosie\\\";\\n\\t\\tslalom(mySkier,mySpeed,myName);\\n\\t}\\n}\",\r\n    \"img\" : \"D:\\\\LICENTA\\\\Intrebari_XML\\\\question_image\\\\c615png.png\",\r\n    \"textDown\" : \"\\nSelect the correct answer.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"A\"\r\n  }, {\r\n    \"respoonse\" : \"B\"\r\n  }, {\r\n    \"respoonse\" : \"C\"\r\n  }, {\r\n    \"respoonse\" : \"D\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(266, 'CQ600468', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600468\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"61\",\r\n    \"name\" : \"Create methods with arguments and return values; including overloaded methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the class below, which method signature could be successfully added to the class as\\nan overloaded version of the findAverage() method?\",\r\n    \"code\" : \"public class Calculations {\\n\\tpublic Integer findAverage(int sum) { return sum; }\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"public Long findAverage(int sum)\"\r\n  }, {\r\n    \"respoonse\" : \"public Long findAverage(int sum, int divisor)\"\r\n  }, {\r\n    \"respoonse\" : \"public Integer average(int sum)\"\r\n  }, {\r\n    \"respoonse\" : \"private void findAverage(int sum)\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(267, 'CQ600266', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600266\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"65\",\r\n    \"name\" : \"Apply encapsulation principles to a class\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is not a reason to use encapsulation when designing a class?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Promote usability by other developers.\"\r\n  }, {\r\n    \"respoonse\" : \"Maintain class data integrity of data elements.\"\r\n  }, {\r\n    \"respoonse\" : \"Prevent users from modifying the internal attributes of a class.\"\r\n  }, {\r\n    \"respoonse\" : \"Increase concurrency and improve performance.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
