(271, 'CQ600614', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600614\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"62\",\r\n    \"name\" : \"Apply the static keyword to methods and fields\"\r\n  }, {\r\n    \"id\" : \"63\",\r\n    \"name\" : \"Create and overload constructors; differentiate between default and user defined constructors\"\r\n  }, {\r\n    \"id\" : \"64\",\r\n    \"name\" : \"Apply access modifiers\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many final modifiers would need to be removed for this application to compile?\",\r\n    \"code\" : \"package end;\\npublic final class Games {\\n\\tpublic final static int finish(final int score) {\\n\\t\\tfinal int win = 3;\\n\\t\\tfinal int result = score++ < 5 ? 2 : win;\\n\\t\\treturn result+=win;\\n\\t}\\n\\tpublic static void main(final String[] v) {\\n\\t\\tSystem.out.print(finish(Integer.parseInt(v[0])));\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"None\"\r\n  }, {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"The code will not compile regardless of the number of final modifiers that are removed.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(272, 'CQ600710', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ600710\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"63\",\r\n    \"name\" : \"Create and overload constructors; differentiate between default and user defined constructors\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks ________________: is used to call a constructor in the parent class,\\nwhile ________________________ is used to reference a member of the parent class.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"super and this()\"\r\n  }, {\r\n    \"respoonse\" : \"super and super()\"\r\n  }, {\r\n    \"respoonse\" : \"super() and this\"\r\n  }, {\r\n    \"respoonse\" : \"super() and super\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
