(274, 'CQ600611', '{\r\n  \"format\" : \"TEXT_UP_COD_TEXT_DOWN\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600611\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"65\",\r\n    \"name\" : \"Apply encapsulation principles to a class\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement(s) about the following class would help to properly encapsulate the data in\\nthe class?\",\r\n    \"code\" : \"package shield;\\npublic class Protect {\\n\\tprivate String material;\\n\\tprotected int strength;\\n\\n\\tpublic int getStrength() {\\n\\t\\treturn strength;\\n\\t}\\n\\tpublic void setStrength(int strength) {\\n\\t\\tthis.strength = strength;\\n\\t}\\n}\",\r\n    \"textDown\" : \"I. Change the access modifier of strength to private.\\nII. Add a getter method for material.\\nIII. Add a setter method for material.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I\"\r\n  }, {\r\n    \"respoonse\" : \"II and III\"\r\n  }, {\r\n    \"respoonse\" : \"I, II, and III\"\r\n  }, {\r\n    \"respoonse\" : \"None, the data in the class is already encapsulated.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
