(278, 'CQ600549', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600549\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"63\",\r\n    \"name\" : \"Create and overload constructors; differentiate between default and user defined constructors\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is a possible output of the following application?\",\r\n    \"code\" : \"package wrap;\\npublic class Gift {\\n\\tprivate final Object contents;\\n\\tprotected Object getContents() {\\n\\t\\treturn contents;\\n\\t}\\n\\tprotected void setContents(Object contents) {\\n\\t\\tthis.contents = contents;\\n\\t}\\n\\tpublic void showPresent() {\\n\\t\\tSystem.out.print(\\\"Your gift: \\\"+contents);\\n\\t}\\n\\tpublic static void main(String[] treats) {\\n\\t\\tGift gift = new Gift();\\n\\t\\tgift.setContents(gift);\\n\\t\\tgift.showPresent();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Your gift: wrap.Gift@29ca2745\"\r\n  }, {\r\n    \"respoonse\" : \"Your gift: Your gift:\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"It compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
