(280, 'CQ600895', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ600895\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"62\",\r\n    \"name\" : \"Apply the static keyword to methods and fields\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following two classes, each in a different package, which line inserted below\\nallows the second class to compile?\",\r\n    \"code\" : \"package clothes;\\npublic class Store {\\n\\tpublic static String getClothes() { return \\\"dress\\\"; }\\n}\\n\\npackage wardrobe;\\n// INSERT CODE HERE\\npublic class Closet {\\n\\tpublic void borrow() {\\n\\t\\tSystem.out.print(\\\"Borrowing clothes: \\\"+getClothes());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"static import clothes.Store.getClothes;\"\r\n  }, {\r\n    \"respoonse\" : \"import clothes.Store.*;\"\r\n  }, {\r\n    \"respoonse\" : \"import static clothes.Store.getClothes;\"\r\n  }, {\r\n    \"respoonse\" : \"import static clothes.Store;\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
