(285, 'CQ600986', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600986\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"61\",\r\n    \"name\" : \"Create methods with arguments and return values; including overloaded methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements about overloaded methods are true?\\t\\n\\tI. Overloaded methods must have the same name.\\n\\tII. Overloaded methods must have the same return type.\\n\\tIII. Overloaded methods must have a different list of parameters.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I\"\r\n  }, {\r\n    \"respoonse\" : \"I and II\"\r\n  }, {\r\n    \"respoonse\" : \"I and III\"\r\n  }, {\r\n    \"respoonse\" : \"I, II, and III\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(286, 'CQ600970', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ600970\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"66\",\r\n    \"name\" : \"Determine the effect upon object references and primitive values when they are passed into methods that change the values\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many lines of code would need to be removed for the following class to compile?\",\r\n    \"code\" : \"package work;\\npublic class Week {\\n\\tprivate static final String monday;\\n\\tString tuesday;\\n\\tfinal static wednesday = 3;\\n\\tfinal protected int thursday = 4;\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"Three\"\r\n  }, {\r\n    \"respoonse\" : \"The code will not compile regardless of the number of lines removed.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(287, 'CQ600645', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600645\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"65\",\r\n    \"name\" : \"Apply encapsulation principles to a class\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package pet;\\npublic class Puppy {\\n\\tpublic static int wag = 5; // q1\\n\\tpublic void Puppy(int wag) { // q2\\n\\t\\tthis.wag = wag;\\n\\t}\\n\\tpublic static void main(String[] tail) {\\n\\t\\tSystem.out.print(new Puppy(2).wag); // q3\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile because of line q1.\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile because of line q2.\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile because of line q3.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
