(290, 'CQ600936', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600936\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"66\",\r\n    \"name\" : \"Determine the effect upon object references and primitive values when they are passed into methods that change the values\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following class, which line of code when inserted below would prevent the class\\nfrom compiling?\",\r\n    \"code\" : \"public class Drink {\\n\\tpublic static void water() {}\\n\\tpublic void get() {\\n\\t\\t// INSERT CODE HERE\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"water();\"\r\n  }, {\r\n    \"respoonse\" : \"this.Drink.water();\"\r\n  }, {\r\n    \"respoonse\" : \"this.water();\"\r\n  }, {\r\n    \"respoonse\" : \"Drink.water();\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(291, 'CQ600808', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ600808\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"65\",\r\n    \"name\" : \"Apply encapsulation principles to a class\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following method declaration signature, which of the following is a valid call of\\nthis method?\",\r\n    \"code\" : \"public void call(int count, String me, String... data)\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"call(9,\\\"me\\\",10,\\\"Al\\\")\"\r\n  }, {\r\n    \"respoonse\" : \"call(5)\"\r\n  }, {\r\n    \"respoonse\" : \"call(2,\\\"home\\\",\\\"sweet\\\")\"\r\n  }, {\r\n    \"respoonse\" : \"call(\\\"answering\\\",\\\"service\\\")\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(292, 'CQ600533', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600533\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"62\",\r\n    \"name\" : \"Apply the static keyword to methods and fields\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about a static variable is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The value of a static variable must be set when the variable is declared or in a static initialization block.\"\r\n  }, {\r\n    \"respoonse\" : \"It is not possible to read static final variables outside the class in which they are defined.\"\r\n  }, {\r\n    \"respoonse\" : \"It is not possible to reference static methods using static imports.\"\r\n  }, {\r\n    \"respoonse\" : \"A static variable is always available in all instances of the class.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(293, 'CQ600424', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600424\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"63\",\r\n    \"name\" : \"Create and overload constructors; differentiate between default and user defined constructors\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is not a true statement?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The first line of every constructor is a call to the parent constructor via the super() command.\"\r\n  }, {\r\n    \"respoonse\" : \"A class does not have to have a constructor explicitly defined.\"\r\n  }, {\r\n    \"respoonse\" : \"A constructor may pass arguments to the parent constructor.\"\r\n  }, {\r\n    \"respoonse\" : \"A final instance variable whose value is not set when they are declared or in an initialization block should be set by the constructor.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(294, 'CQ600968', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600968\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"62\",\r\n    \"name\" : \"Apply the static keyword to methods and fields\"\r\n  }, {\r\n    \"id\" : \"64\",\r\n    \"name\" : \"Apply access modifiers\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many final modifiers would need to be removed for this application to compile?\",\r\n    \"code\" : \"package park;\\npublic class Tree {\\n\\tpublic final static long numberOfTrees;\\n\\tpublic final double height;\\n\\tstatic {}\\n\\t{ final int initHeight = 2;\\n\\theight = initHeight;\\n\\t}\\n\\tstatic {\\n\\t\\tnumberOfTrees = 100;\\n\\t\\theight = 4;\\n\\t}\\n}\\t\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"None\"\r\n  }, {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"The code will not compile regardless of the number of final modifiers removed.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(295, 'CQ600822', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ600822\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"61\",\r\n    \"name\" : \"Create methods with arguments and return values; including overloaded methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package jungle;\\npublic class RainForest extends Forest {\\n\\tpublic RainForest(long treeCount) {\\n\\t\\tthis.treeCount = treeCount+1;\\n\\t}\\n\\tpublic static void main(String[] birds) {\\n\\t\\tSystem.out.print(new RainForest(5).treeCount);\\n\\t}\\n}\\nclass Forest {\\n\\tpublic long treeCount;\\n\\tpublic Forest(long treeCount) {\\n\\tthis.treeCount = treeCount+2;\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"5\"\r\n  }, {\r\n    \"respoonse\" : \"6\"\r\n  }, {\r\n    \"respoonse\" : \"8\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(296, 'CQ600989', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600989\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"61\",\r\n    \"name\" : \"Create methods with arguments and return values; including overloaded methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"public class ChooseWisely {\\n\\tpublic ChooseWisely() { super(); }\\n\\tpublic int choose(int choice) { return 5; }\\n\\tpublic int choose(short choice) { return 2; }\\n\\tpublic int choose(long choice) { return 11; }\\n\\tpublic static void main(String[] path) {\\n\\t\\tSystem.out.print(new ChooseWisely().choose((byte)2+1));\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"5\"\r\n  }, {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"11\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(297, 'CQ600812', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600812\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"61\",\r\n    \"name\" : \"Create methods with arguments and return values; including overloaded methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package sports;\\npublic class Football {\\n\\tpublic static Long getScore(Long timeRemaining) {\\n\\t\\treturn 2*timeRemaining; // m1\\n\\t}\\n\\tpublic static void main(String[] refs) {\\n\\t\\tfinal int startTime = 4;\\n\\t\\t(getScore(startTime)); // m2\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"8\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line m1.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line m2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(298, 'CQ600590', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ600590\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"61\",\r\n    \"name\" : \"Create methods with arguments and return values; including overloaded methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is a valid method name in Java?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"$sprint()\"\r\n  }, {\r\n    \"respoonse\" : \"\\\\jog13()\"\r\n  }, {\r\n    \"respoonse\" : \"walk#()\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(299, 'CQ600559', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ600559\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"64\",\r\n    \"name\" : \"Apply access modifiers\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Assume there is a class Bouncer with a protected variable. Methods in which class can\\naccess this variable?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Only subclasses of Bouncer\"\r\n  }, {\r\n    \"respoonse\" : \"Any subclass of Bouncer or any class in the same package as Bouncer\"\r\n  }, {\r\n    \"respoonse\" : \"Only classes in the same package as Bouncer\"\r\n  }, {\r\n    \"respoonse\" : \"Any superclass of Bouncer\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(300, 'CQ600304', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ600304\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"6\",\r\n    \"name\" : \"Working with Methods and Encapsulation\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"62\",\r\n    \"name\" : \"Apply the static keyword to methods and fields\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following two classes, each in a different package, which line inserted below\\nallows the second class to compile?\",\r\n    \"code\" : \"package commerce;\\npublic class Bank {\\n\\tpublic void withdrawal(int amountInCents) {}\\n\\tpublic void deposit(int amountInCents) {}\\n}\\n\\npackage employee;\\n// INSERT CODE HERE\\npublic class Teller {\\n\\tpublic void processAccount(int depositSlip, int withdrawalSlip) {\\n\\t\\twithdrawal(withdrawalSlip);\\n\\t\\tdeposit(depositSlip);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"import static commerce.Bank.*;\"\r\n  }, {\r\n    \"respoonse\" : \"static import commerce.Bank.*;\"\r\n  }, {\r\n    \"respoonse\" : \"import static commerce.Bank;\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(301, 'CQ700170', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700170\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many lines of the following program contain compilation errors?\",\r\n    \"code\" : \"package theater;\\nclass Cinema {\\n\\tprivate String name;\\n\\tpublic Cinema(String name) {this.name = name;}\\n}\\npublic class Movie extends Cinema {\\n\\tpublic Movie(String movie) {}\\n\\tpublic static void main(String[] showing) {\\n\\t\\tSystem.out.print(new Movie(\\\"Another Trilogy\\\").name);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"None\"\r\n  }, {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"Three\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
