(303, 'CQ700658', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700658\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package radio;\\npublic class Song {\\n\\tpublic void playMusic() {\\n\\t\\tSystem.out.print(\\\"Play!\\\");\\n\\t}\\n\\tprivate static int playMusic() {\\n\\t\\tSystem.out.print(\\\"Music!\\\");\\n\\t}\\n\\tpublic static void main(String[] tracks) {\\n\\t\\tnew Song().playMusic();\\n\\t}\\t\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Play!\"\r\n  }, {\r\n    \"respoonse\" : \"Music!\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but the answer cannot be determined until runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(304, 'CQ700354', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700354\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements about inheritance is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Inheritance allows objects to access commonly used attributes and methods.\"\r\n  }, {\r\n    \"respoonse\" : \"Inheritance always leads to simpler code.\"\r\n  }, {\r\n    \"respoonse\" : \"All primitives and objects inherit a set of methods.\"\r\n  }, {\r\n    \"respoonse\" : \"Inheritance allows you to write methods that reference themselves.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(305, 'CQ700966', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700966\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the class declaration below, which value cannot be inserted into the blank line that\\nwould allow the code to compile?\",\r\n    \"code\" : \"package mammal;\\ninterface Pet {}\\npublic class Canine implements Pet {\\n\\tpublic ______________ getDoggy() {\\n\\t\\treturn this;\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Class\"\r\n  }, {\r\n    \"respoonse\" : \"Pet\"\r\n  }, {\r\n    \"respoonse\" : \"Canine\"\r\n  }, {\r\n    \"respoonse\" : \"Object\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(306, 'CQ700509', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700509\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Imagine you are working with another team to build an application. You are developing\\ncode that uses a class that the other team has not finished writing yet. Which element of\\nJava would best facilitate this development, allowing easy integration once the other team’s\\ncode is complete?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"An abstract class\"\r\n  }, {\r\n    \"respoonse\" : \"An interface\"\r\n  }, {\r\n    \"respoonse\" : \"static methods\"\r\n  }, {\r\n    \"respoonse\" : \"An access modifier\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(307, 'CQ700822', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700822\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"74\",\r\n    \"name\" : \"Use super and this to access objects and constructors\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package vehicles;\\nclass Automobile {\\n\\tprivate final String drive() { return \\\"Driving vehicle\\\"; }\\n}\\nclass Car extends Automobile {\\n\\tprotected String drive() { return \\\"Driving car\\\"; }\\n}\\npublic class ElectricCar extends Car {\\n\\tpublic final String drive() { return \\\"Driving electric car\\\"; }\\n\\tpublic static void main(String[] wheels) {\\n\\t\\tfinal Car car = new ElectricCar();\\n\\t\\tSystem.out.print(car.drive());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Driving vehicle\"\r\n  }, {\r\n    \"respoonse\" : \"Driving electric car\"\r\n  }, {\r\n    \"respoonse\" : \"Driving car\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(308, 'CQ700442', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700442\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements about inheritance is correct?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Java does not support multiple inheritance.\"\r\n  }, {\r\n    \"respoonse\" : \"Java allows multiple inheritance using abstract classes.\"\r\n  }, {\r\n    \"respoonse\" : \"Java allows multiple inheritance using non-abstract classes.\"\r\n  }, {\r\n    \"respoonse\" : \"Java allows multiple inheritance using interfaces.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(309, 'CQ700210', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700210\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many changes need to be made to the classes below to properly override the watch()\\nmethod?\",\r\n    \"code\" : \"package entertainment;\\nclass Television {\\n\\tprotected final void watch() {}\\n}\\npublic class LCD extends Television {\\n\\tObject watch() {}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"Three\"\r\n  }, {\r\n    \"respoonse\" : \"None; the code compiles as is.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(310, 'CQ700633', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700633\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements about overriding a method is incorrect?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The return types must be covariant.\"\r\n  }, {\r\n    \"respoonse\" : \"The access modifier of the method in the child class must be the same or broader than the method in the superclass.\"\r\n  }, {\r\n    \"respoonse\" : \"A checked exception thrown by the method in the parent class must be thrown by the method in the child class.\"\r\n  }, {\r\n    \"respoonse\" : \"A checked exception thrown by a method in the child class must be the same or narrower than the exception thrown by the method in the parent class.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(311, 'CQ700836', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700836\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package machines;\\nclass Computer {\\n\\tprotected final int process() { return 5; }\\n}\\npublic class Laptop extends Computer {\\n\\tpublic final int process() { return 3; }\\n\\tpublic static void main(String[] chips) {\\n\\t\\tSystem.out.print(new Laptop().process());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"5\"\r\n  }, {\r\n    \"respoonse\" : \"3\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(312, 'CQ700907', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700907\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given that FileNotFoundException is a subclass of IOException, what is the output of\\nthe following application?\",\r\n    \"code\" : \"package edu;\\nimport java.io.*;\\nclass School {\\n\\tpublic int getNumberOfStudentsPerClassroom(String... students)\\n\\t\\tthrows IOException {\\n\\t\\treturn 3;\\n\\t}\\n\\tpublic int getNumberOfStudentsPerClassroom() throws IOException {\\n\\t\\treturn 9;\\n\\t}\\n}\\npublic class HighSchool extends School {\\n\\tpublic int getNumberOfStudentsPerClassroom() throws FileNotFoundException {\\n\\t\\treturn 2;\\n\\t}\\n\\tpublic static void main(String[] students) throws IOException {\\n\\t\\tSchool school = new HighSchool();\\n\\t\\tSystem.out.print(school.getNumberOfStudentsPerClassroom());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"3\"\r\n  }, {\r\n    \"respoonse\" : \"9\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(313, 'CQ700990', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700990\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which modifier can be applied to an interface method?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"protected\"\r\n  }, {\r\n    \"respoonse\" : \"static\"\r\n  }, {\r\n    \"respoonse\" : \"private\"\r\n  }, {\r\n    \"respoonse\" : \"final\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(314, 'CQ700205', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700205\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package track;\\ninterface Run {\\n\\tdefault void walk() {\\n\\t\\tSystem.out.print(\\\"Walking and running!\\\");\\n\\t}\\n}\\ninterface Jog {\\n\\tdefault void walk() {\\n\\t\\tSystem.out.print(\\\"Walking and jogging!\\\");\\n\\t}\\n}\\npublic class Sprint implements Run, Jog {\\n\\tpublic void walk() {\\n\\t\\tSystem.out.print(\\\"Sprinting!\\\");\\n\\t}\\n\\tpublic static void main() {\\n\\t\\tnew Sprint().walk();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Walking and running!\"\r\n  }, {\r\n    \"respoonse\" : \"Walking and jogging!\"\r\n  }, {\r\n    \"respoonse\" : \"Sprinting!\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java');
