(315, 'CQ700297', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700297\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements about interfaces is not true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"An interface can extend another interface.\"\r\n  }, {\r\n    \"respoonse\" : \"An interface can implement another interface.\"\r\n  }, {\r\n    \"respoonse\" : \"A class can implement two interfaces.\"\r\n  }, {\r\n    \"respoonse\" : \"A class can extend another class.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(316, 'CQ700600', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700600\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package transport;\\n\\nclass Ship {\\n\\tprotected int weight = 3;\\n\\tprivate int height = 5;\\n\\tpublic int getWeight() { return weight; }\\n\\tpublic int getHeight() { return height; }\\n}\\n\\npublic class Rocket extends Ship {\\n\\tpublic int weight = 2;\\n\\tpublic int height = 4;\\n\\tpublic void printDetails() {\\n\\t\\tSystem.out.print(super.getWeight()+\\\",\\\"+super.height);\\n\\t}\\n\\tpublic static final void main(String[] fuel) {\\n\\t\\tnew Rocket().printDetails();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2, 5\"\r\n  }, {\r\n    \"respoonse\" : \"3, 4\"\r\n  }, {\r\n    \"respoonse\" : \"3, 5\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"no\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(317, 'CQ700433', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700433\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: Excluding default and static methods, a(n) __________________________\\ncan contain both abstract and concrete methods, while a(n) ________________________\\ncontains only abstract methods.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"concrete class, abstract class\"\r\n  }, {\r\n    \"respoonse\" : \"concrete class, interface\"\r\n  }, {\r\n    \"respoonse\" : \"interface, abstract class\"\r\n  }, {\r\n    \"respoonse\" : \"abstract class, interface\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(318, 'CQ700742', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700742\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about the following class is correct?\",\r\n    \"code\" : \"package shapes;\\nabstract class Triangle {\\n\\tabstract String getDescription();\\n}\\nclass RightTriangle extends Triangle {\\n\\tprotected String getDescription() { return \\\"rt\\\"; } // g1\\n}\\npublic abstract class IsoscelesRightTriangle extends RightTriangle { // g2\\n\\tpublic String getDescription() { return \\\"irt\\\"; }\\n\\tpublic static void main(String[] edges) {\\n\\t\\tfinal Triangle shape = new IsoscelesRightTriangle(); // g3\\n\\t\\tSystem.out.print(shape.getDescription());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile due to line g1.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile due to line g2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile due to line g3.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles and runs without issue.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(319, 'CQ700429', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700429\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given that Short and Integer extend Number, what type can be used to fill in the blank in\\nthe class below to allow it to compile?\",\r\n    \"code\" : \"package band;\\n\\ninterface Horn { public Integer play(); }\\nabstract class Woodwind { public Short play() {return 3;} }\\npublic final class Saxophone extends Woodwind implements Horn {\\n\\tpublic ________________ play() {\\n\\t\\treturn null;\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Integer\"\r\n  }, {\r\n    \"respoonse\" : \"Short\"\r\n  }, {\r\n    \"respoonse\" : \"Number\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(320, 'CQ700928', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700928\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: A class_____________________ an interface, while a class\\n___________________________ an abstract class.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"extends, implements\"\r\n  }, {\r\n    \"respoonse\" : \"extends, extends\"\r\n  }, {\r\n    \"respoonse\" : \"implements, extends\"\r\n  }, {\r\n    \"respoonse\" : \"implements, implements\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(321, 'CQ700298', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700298\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package paper;\\n\\nabstract class Book {\\n\\tprotected static String material = \\\"papyrus\\\";\\n\\tpublic Book() {}\\n\\tpublic Book(String material) {this.material = material;}\\n}\\npublic class Encyclopedia extends Book {\\n\\tpublic static String material = \\\"cellulose\\\";\\n\\tpublic Encyclopedia() {super();}\\n\\tpublic String getMaterial() {return super.material;}\\n\\tpublic static void main(String[] pages) {\\n\\t\\tSystem.out.print(new Encyclopedia().getMaterial());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"papyrus\"\r\n  }, {\r\n    \"respoonse\" : \"cellulose\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(322, 'CQ700394', '{\r\n  \"format\" : \"TEXT_UP_IMG_RASPUNSURI\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700394\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"The following diagram shows two reference variables pointing to the same Bunny object\\nin memory. The reference variable myBunny is of type Bunny, while unknownBunny is\\nof an unknown data type. Which statement about the reference variables is not true?\\nFor this question, assume the instance methods and variables shown in the diagram are\\nmarked public.\",\r\n    \"img\" : \"D:\\\\LICENTA\\\\Intrebari_XML\\\\question_image\\\\c722.png\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"If the unknownBunny reference does not have access to the same variables and methods that myBunny has access to, it can be explicitly cast to a reference type that does.\"\r\n  }, {\r\n    \"respoonse\" : \"The data type of unknownBunny must be Bunny or a subclass of Bunny.\"\r\n  }, {\r\n    \"respoonse\" : \"If the data type of unknownBunny is Bunny, it has access to all of the same methods and variables as myBunny.\"\r\n  }, {\r\n    \"respoonse\" : \"The data type of unknownBunny could be an interface, class, or abstract class.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(323, 'CQ700136', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700136\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following modifiers can be applied to an abstract method?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"final\"\r\n  }, {\r\n    \"respoonse\" : \"private\"\r\n  }, {\r\n    \"respoonse\" : \"default\"\r\n  }, {\r\n    \"respoonse\" : \"protected\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(324, 'CQ700130', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700130\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package space;\\n\\ninterface Sphere {\\n\\tdefault String getName() { return \\\"Unknown\\\"; }\\n}\\nabstract class Planet {\\n\\tabstract String getName();\\n}\\npublic class Mars extends Sphere implements Planet {\\n\\tpublic Mars() {\\n\\t\\tsuper();\\n\\t}\\n\\tpublic String getName() { return \\\"Mars\\\"; }\\n\\tpublic static void main(final String[] probe) {\\n\\t\\tSystem.out.print(((Planet)new Mars()).getName());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Mars\"\r\n  }, {\r\n    \"respoonse\" : \"Unknown\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile due to the declaration of Sphere.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile for another reason.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
