(329, 'CQ700556', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700556\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"74\",\r\n    \"name\" : \"Use super and this to access objects and constructors\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package sports;\\nabstract class Ball {\\n\\tprotected final int size;\\n\\tpublic Ball(int size) {\\n\\t\\tthis.size = size;\\n\\t}\\n}\\ninterface Equipment {}\\npublic class SoccerBall extends Ball implements Equipment {\\n\\tpublic SoccerBall() {\\n\\t\\tsuper(5);\\n\\t}\\n\\tpublic Ball get() { return this; }\\n\\tpublic static void main(String[] passes) {\\n\\t\\tEquipment equipment = (Equipment)(Ball)new SoccerBall().get();\\n\\t\\tSystem.out.print(((SoccerBall)equipment).size);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"5\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile due an invalid cast.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile for a different reason.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws a ClassCastException at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(330, 'CQ700254', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700254\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: A class that defines an instance variable with the same name as a variable\\nin the parent class is referred to as _________________________ a variable, while a class that\\ndefines a static method with the same signature as a static method in a parent class is\\nreferred to as ________________________ a method.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"hiding, overriding\"\r\n  }, {\r\n    \"respoonse\" : \"overriding, hiding\"\r\n  }, {\r\n    \"respoonse\" : \"hiding, hiding\"\r\n  }, {\r\n    \"respoonse\" : \"replacing, overriding\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
