(340, 'CQ700291', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700291\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"class Math {\\n\\tpublic final double secret = 2;\\n}\\nclass ComplexMath extends Math {\\n\\tpublic final double secret = 4;\\n}\\npublic class InfiniteMath extends ComplexMath {\\n\\tpublic final double secret = 8;\\n\\tpublic static void main(String[] numbers) {\\n\\t\\tMath math = new InfiniteMath();\\n\\t\\tSystem.out.print(math.secret);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2\"\r\n  }, {\r\n    \"respoonse\" : \"4\"\r\n  }, {\r\n    \"respoonse\" : \"8\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(341, 'CQ700908', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700908\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following method and the fact that FileNotFoundException is a subclass of\\nIOException, which of the following method signatures is a valid override by a subclass?\\nprotected void dance() throws FileNotFoundException {}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"void dance() throws IOException\"\r\n  }, {\r\n    \"respoonse\" : \"public void dance() throws IOException\"\r\n  }, {\r\n    \"respoonse\" : \"private void dance() throws FileNotFoundException\"\r\n  }, {\r\n    \"respoonse\" : \"public final void dance()\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(342, 'CQ700321', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700321\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the class definitions below, which value, when inserted into the blank line, does not\\nallow the class to compile?\",\r\n    \"code\" : \"public class Canine {}\\npublic class Dog extends Canine {}\\npublic class Wolf extends Canine {}\\npublic final class Husky extends Dog {}\\npublic class Zoologist {\\n\\tCanine animal;\\n\\tpublic final void setAnimal(Dog animal) { this.animal = animal; }\\n\\tpublic static void main(String[] furryFriends) {\\n\\t\\tnew Zoologist().setAnimal(______________________ );\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"new Husky()\"\r\n  }, {\r\n    \"respoonse\" : \"new Dog()\"\r\n  }, {\r\n    \"respoonse\" : \"new Wolf()\"\r\n  }, {\r\n    \"respoonse\" : \"null\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(343, 'CQ700415', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700415\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following modifiers cannot be applied to an interface method?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"final\"\r\n  }, {\r\n    \"respoonse\" : \"default\"\r\n  }, {\r\n    \"respoonse\" : \"static\"\r\n  }, {\r\n    \"respoonse\" : \"abstract\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(344, 'CQ700516', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700516\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which statement about the following application is true?\",\r\n    \"code\" : \"package party;\\n\\nabstract class House {\\n\\tprotected abstract Object getSpace();\\n}\\nabstract class Room extends House {\\n\\tabstract Object getSpace(Object list);\\n}\\nabstract public class Ballroom extends House {\\n\\tprotected abstract Object getSpace();\\n\\tpublic static void main(String[] squareFootage) {\\n\\t\\tSystem.out.print(\\\"Let\'s start the party!\\\");\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"It compiles and at runtime prints Let\'s start the party!\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile for one reason.\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile for two reasons.\"\r\n  }, {\r\n    \"respoonse\" : \"It does not compile for three reasons.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(345, 'CQ700726', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700726\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"73\",\r\n    \"name\" : \"Determine when casting is necessary\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: _________________________ methods must have a different list of parameters,\\nwhile ______________________________ methods must have the exact same return type.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Overloaded, overridden\"\r\n  }, {\r\n    \"respoonse\" : \"Inherited, overridden\"\r\n  }, {\r\n    \"respoonse\" : \"Overridden, overloaded\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(346, 'CQ700929', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ700929\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements about no-argument constructors is correct?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"If a parent class does not include a no-argument constructor, a child class cannot declare one.\"\r\n  }, {\r\n    \"respoonse\" : \"If a parent class does not include a no-argument constructor (nor a default one inserted by the compiler), a child class must contain at least one constructor definition.\"\r\n  }, {\r\n    \"respoonse\" : \"If a parent class contains a no-argument constructor, a child class must contain a no-argument constructor.\"\r\n  }, {\r\n    \"respoonse\" : \"If a parent class contains a no-argument constructor, a child class must contain at least one constructor.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(347, 'CQ700349', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700349\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: The ___________________________ determines which attributes exist in\\nmemory, while the _________________________ determines which attributes are accessible\\nby the caller.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"reference type, signature\"\r\n  }, {\r\n    \"respoonse\" : \"object type, superclass\"\r\n  }, {\r\n    \"respoonse\" : \"reference type, object type\"\r\n  }, {\r\n    \"respoonse\" : \"object type, reference type\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(348, 'CQ700330', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700330\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"73\",\r\n    \"name\" : \"Determine when casting is necessary\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given that Integer and Long are subclasses of Number, what type can be used to fill in\\nthe blank in the class below to allow it to compile?\",\r\n    \"code\" : \"package orchestra;\\ninterface MusicCreator { public Number play(); }\\nabstract class StringInstrument { public Long play() {return 3L;} }\\npublic class Violin extends StringInstrument implements MusicCreator {\\n\\tpublic __________________ play() {\\n\\t\\treturn 12;\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Long\"\r\n  }, {\r\n    \"respoonse\" : \"Integer\"\r\n  }, {\r\n    \"respoonse\" : \"Long or Integer\"\r\n  }, {\r\n    \"respoonse\" : \"Long or Number\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(349, 'CQ700686', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ700686\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is the best reason for creating a default interface method?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Allow interface methods to be inherited.\"\r\n  }, {\r\n    \"respoonse\" : \"Add backward compatibility to existing interfaces.\"\r\n  }, {\r\n    \"respoonse\" : \"Give an interface the ability to create concrete methods.\"\r\n  }, {\r\n    \"respoonse\" : \"Allow an interface to define a method at the class level.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java');
