(350, 'CQ700399', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ700399\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"7\",\r\n    \"name\" : \"Working with Inheritance\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"71\",\r\n    \"name\" : \"Describe inheritance and its benefits\"\r\n  }, {\r\n    \"id\" : \"72\",\r\n    \"name\" : \"Develop code that makes use of polymorphism; develop code that overrides methods; differentiate between the type of a reference and the type of an object\"\r\n  }, {\r\n    \"id\" : \"73\",\r\n    \"name\" : \"Determine when casting is necessary\"\r\n  }, {\r\n    \"id\" : \"74\",\r\n    \"name\" : \"Use super and this to access objects and constructors\"\r\n  }, {\r\n    \"id\" : \"75\",\r\n    \"name\" : \"Use abstract classes and interfaces\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given that EOFException is a subclass of IOException, what is the output of the following\\napplication?\",\r\n    \"code\" : \"package ai;\\nimport java.io.*;\\nclass Machine {\\n\\tpublic boolean turnOn() throws EOFException {return true;}\\n}\\npublic class Robot extends Machine {\\n\\tpublic boolean turnOn() throws IOException {return false;}\\n\\tpublic static void main(String[] doesNotCompute) throws Exception {\\n\\t\\tMachine m = new Robot();\\n\\t\\tSystem.out.print(m.turnOn());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"true\"\r\n  }, {\r\n    \"respoonse\" : \"false\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but produces an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(351, 'CQ800944', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800944\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"81\",\r\n    \"name\" : \"Differentiate among checked exceptions, unchecked exceptions, and Errors\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of compiling and executing the following application?\",\r\n    \"code\" : \"package mind;\\npublic class Remember {\\n\\tpublic static void think() throws Exception { // k1\\n\\t\\ttry {\\n\\t\\t\\tthrow new Exception();\\n\\t\\t}\\n\\t}\\n\\tpublic static void main(String... ideas) throws Exception {\\n\\t\\tthink();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code compiles and runs without printing anything.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but a stack trace is printed at runtime.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line k1.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile for another reason.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
