(355, 'CQ800964', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800964\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  }, {\r\n    \"id\" : \"83\",\r\n    \"name\" : \"Describe the advantages of Exception handling\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package game;\\npublic class Baseball {\\n\\tpublic static void main(String... teams) {\\n\\t\\ttry {\\n\\t\\t\\tint score = 1;\\n\\t\\t\\tSystem.out.print(score++);\\n\\t\\t} catch (Throwable t) {\\n\\t\\t\\tSystem.out.print(score++);\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(score++);\\n\\t\\t}\\n\\t\\t\\tSystem.out.print(score++);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"123\"\r\n  }, {\r\n    \"respoonse\" : \"124\"\r\n  }, {\r\n    \"respoonse\" : \"12\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(356, 'CQ800994', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ800994\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is a checked exception?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"ClassCastException\"\r\n  }, {\r\n    \"respoonse\" : \"IOException\"\r\n  }, {\r\n    \"respoonse\" : \"ArrayIndexOutOfBoundsException\"\r\n  }, {\r\n    \"respoonse\" : \"IllegalArgumentException\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(357, 'CQ800688', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ800688\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: The _________________ keyword is used in method declarations,\\nwhile the ___________________________ keyword is used to throw an exception to the\\nsurrounding process.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"throws, throw\"\r\n  }, {\r\n    \"respoonse\" : \"catch, throw\"\r\n  }, {\r\n    \"respoonse\" : \"throw, throws\"\r\n  }, {\r\n    \"respoonse\" : \"throws, catch\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(358, 'CQ800511', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800511\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  }, {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"If a try statement has catch blocks for both Exception and IOException, then which of\\nthe following statements is correct?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The catch block for Exception must appear before the catch block for IOException.\"\r\n  }, {\r\n    \"respoonse\" : \"The catch block for IOException must appear before the catch block for Exception.\"\r\n  }, {\r\n    \"respoonse\" : \"The catch blocks for these two exception types can be declared in any order.\"\r\n  }, {\r\n    \"respoonse\" : \"A try statement cannot be declared with these two catch block types because they are incompatible.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(359, 'CQ800906', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800906\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  }, {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package game;\\npublic class Football {\\n\\tpublic static void main(String officials[]) {\\n\\t\\ttry {\\n\\t\\t\\tSystem.out.print(\'A\');\\n\\t\\t\\tthrow new RuntimeException(\\\"Out of bounds!\\\");\\n\\t\\t} catch (ArrayIndexOutOfBoundsException aioobe) {\\n\\t\\t\\tSystem.out.print(\'B\');\\n\\t\\t\\tthrow t;\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(\'C\');\\n\\t\\t}\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"ABC\"\r\n  }, {\r\n    \"respoonse\" : \"ABC, followed by a stack trace for a RuntimeException\"\r\n  }, {\r\n    \"respoonse\" : \"AC, followed by a stack trace for a RuntimeException\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(360, 'CQ800223', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800223\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of compiling and running the following application?\",\r\n    \"code\" : \"package castles;\\npublic class Fortress {\\n\\tpublic void openDrawbridge() throws Exception { // p1\\n\\t\\ttry {\\n\\t\\t\\tthrow new Exception(\\\"Circle\\\");\\n\\t\\t} catch (Exception e) {\\n\\t\\t\\tSystem.out.print(\\\"Opening!\\\");\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(\\\"Walls\\\"); // p2\\n\\t}\\n}\\n\\tpublic static void main(String[] moat) {\\n\\t\\tnew Fortress().openDrawbridge(); // p3\\n\\t}\\t\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile because of line p1.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line p2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line p3.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles, but a stack trace is printed at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(361, 'CQ800113', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800113\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following exception types must be handled or declared by the method in\\nwhich they are thrown?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"NullPointerException\"\r\n  }, {\r\n    \"respoonse\" : \"Exception\"\r\n  }, {\r\n    \"respoonse\" : \"RuntimeException\"\r\n  }, {\r\n    \"respoonse\" : \"ArithmeticException\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(362, 'CQ800928', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800928\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  }, {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package game;\\npublic class BasketBall {\\n\\tpublic static void main(String[] dribble) {\\n\\t\\ttry {\\n\\t\\t\\tSystem.out.print(1);\\n\\t\\t\\tthrow new ClassCastException();\\n\\t\\t} catch (ArrayIndexOutOfBoundsException ex) {\\n\\t\\t\\tSystem.out.print(2);\\n\\t\\t} catch (Throwable ex) {\\n\\t\\t\\tSystem.out.print(3);\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(4);\\n\\t\\t}\\n\\t\\tSystem.out.print(5);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"1345\"\r\n  }, {\r\n    \"respoonse\" : \"1235\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(363, 'CQ800922', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800922\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following statements about a finally block is true?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Every line of the finally block is guaranteed to be executed.\"\r\n  }, {\r\n    \"respoonse\" : \"The finally block is executed only if the related catch block is also executed.\"\r\n  }, {\r\n    \"respoonse\" : \"The finally statement requires brackets {}.\"\r\n  }, {\r\n    \"respoonse\" : \"The finally block cannot throw an exception.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(364, 'CQ800562', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800562\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  }, {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given that FileNotFoundException is a subclass of IOException, what is the output of\\nthe following application?\",\r\n    \"code\" : \"package office;\\nimport java.io.*;\\npublic class Printer {\\n\\tpublic void print() {\\n\\t\\ttry {\\n\\t\\t\\tthrow new FileNotFoundException();\\n\\t\\t} catch (IOException exception) {\\n\\t\\t\\tSystem.out.print(\\\"Z\\\");\\n\\t\\t} catch (FileNotFoundException enfe) {\\n\\t\\t\\tSystem.out.print(\\\"X\\\");\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(\\\"Y\\\");\\n\\t\\t}\\n\\t}\\n\\tpublic static void main(String... ink) {\\n\\t\\tnew Printer().print();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"XY\"\r\n  }, {\r\n    \"respoonse\" : \"ZY\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but a stack trace is printed at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(365, 'CQ800629', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800629\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which keywords are required with a try statement?\\nI. catch\\nII. finalize\\nIII. finally\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I only\"\r\n  }, {\r\n    \"respoonse\" : \"II only\"\r\n  }, {\r\n    \"respoonse\" : \"I or III, or both\"\r\n  }, {\r\n    \"respoonse\" : \"None of these statements are required with a try statement.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
