(373, 'CQ800577', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800577\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"81\",\r\n    \"name\" : \"Differentiate among checked exceptions, unchecked exceptions, and Errors\"\r\n  }, {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of compiling and running the following application?\",\r\n    \"code\" : \"package castles;\\nclass CastleUnderSiegeException extends Exception {}\\nclass KnightAttackingException extends CastleUnderSiegeException {}\\npublic class Citadel {\\n\\tpublic void openDrawbridge() throws RuntimeException { // q1\\n\\t\\ttry {\\n\\t\\t\\tthrow new KnightAttackingException();\\n\\t\\t} catch (Exception e) {\\n\\t\\t\\tthrow new ClassCastException();\\n\\t\\t} finally {\\n\\t\\t\\tthrow new CastleUnderSiegeException(); // q2\\n\\t\\t}\\n\\t}\\n\\tpublic static void main(String[] moat) {\\n\\t\\tnew Citadel().openDrawbridge(); // q3\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile because of line q1.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line q2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line q3.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles, but a stack trace is printed at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(374, 'CQ800261', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800261\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"If an exception matches two or more catch blocks, which catch block is executed?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The first one that matches is executed.\"\r\n  }, {\r\n    \"respoonse\" : \"The last one that matches is executed.\"\r\n  }, {\r\n    \"respoonse\" : \"All matched blocks are executed.\"\r\n  }, {\r\n    \"respoonse\" : \"is not possible to write code like this.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(375, 'CQ800730', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800730\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"In the following application, the value of list has been omitted. Assuming the code\\ncompiles without issue, which one of the following is not a possible output of executing\\nthis class?\",\r\n    \"code\" : \"package checkboard;\\n\\npublic class Attendance {\\n\\tprivate Boolean[] list = // value omitted\\n\\tpublic int printTodaysCount() {\\n\\t\\tint count=0;\\n\\t\\tfor(int i=0; i<10; i++) {\\n\\t\\t\\tif(list[i]) ++count;\\n\\t\\t}\\n\\t\\treturn count;\\n\\t}\\n\\tpublic static void main(String[] roster) {\\t\\n\\t\\tnew Attendance().printTodaysCount();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"A stack trace for NullPointerException is printed.\"\r\n  }, {\r\n    \"respoonse\" : \"A stack trace for ArrayIndexOutOfBoundsException is printed.\"\r\n  }, {\r\n    \"respoonse\" : \"A stack trace for ClassCastException is printed.\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(376, 'CQ800161', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800161\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: A ___________________ occurs when a program recurses too deeply\\ninto an infinite loop, while a(n) ____________________ occurs when a reference to a\\nnonexistent object is acted upon.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"NoClassDefFoundError, StackOverflowError\"\r\n  }, {\r\n    \"respoonse\" : \"StackOverflowError, NullPointerException\"\r\n  }, {\r\n    \"respoonse\" : \"ClassCastException, IllegalArgumentException\"\r\n  }, {\r\n    \"respoonse\" : \"StackOverflowError, IllegalArgumentException\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(377, 'CQ800654', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ800654\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"81\",\r\n    \"name\" : \"Differentiate among checked exceptions, unchecked exceptions, and Errors\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the following is not a reason to add checked exceptions to a method signature?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"To force a caller to handle or declare its exceptions\"\r\n  }, {\r\n    \"respoonse\" : \"To notify the caller of potential types of problems\"\r\n  }, {\r\n    \"respoonse\" : \"To ensure that exceptions never cause the application to terminate\"\r\n  }, {\r\n    \"respoonse\" : \"To give the caller a chance to recover from a problem\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(378, 'CQ800800', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800800\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  }, {\r\n    \"id\" : \"84\",\r\n    \"name\" : \"Create and invoke a method that throws an exception\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package peculiar;\\npublic class Stranger {\\n\\tpublic static String getFullName(String firstName, String lastName) {\\n\\t\\ttry {\\n\\t\\t\\treturn firstName.toString() + \\\" \\\" + lastName.toString();\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(\\\"Finished!\\\");\\n\\t\\t} catch (NullPointerException npe) {\\n\\t\\t\\tSystem.out.print(\\\"Problem?\\\");\\n\\t\\t}\\n\\t\\treturn null;\\n\\t}\\n\\tpublic static void main(String[] things) {\\n\\t\\tSystem.out.print(getFullName(\\\"Joyce\\\",\\\"Hopper\\\"));\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Joyce Hopper\"\r\n  }, {\r\n    \"respoonse\" : \"Finished!Joyce Hopper\"\r\n  }, {\r\n    \"respoonse\" : \"Problem?Finished!null\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(379, 'CQ800107', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ800107\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Fill in the blanks: A try statement has ________________________ finally block(s) and\\n__________________________ catch blocks.\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"zero or one, zero or more\"\r\n  }, {\r\n    \"respoonse\" : \"one, one or more\"\r\n  }, {\r\n    \"respoonse\" : \"zero or one, zero or one\"\r\n  }, {\r\n    \"respoonse\" : \"one or more, zero or one\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(380, 'CQ800725', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800725\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"84\",\r\n    \"name\" : \"Create and invoke a method that throws an exception\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package pond;\\nabstract class Duck {\\n\\tprotected int count;\\n\\tpublic abstract int getDuckies();\\n}\\npublic class Ducklings extends Duck {\\n\\tprivate int age;\\n\\tpublic Ducklings(int age) { this.age = age; }\\n\\tpublic int getDuckies() { return this.age/count; }\\n\\tpublic static void main(String[] pondInfo) {\\n\\t\\tDuck itQuacks = new Ducklings(5);\\t\\n\\t\\tSystem.out.print(itQuacks.getDuckies());\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"0\"\r\n  }, {\r\n    \"respoonse\" : \"5\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(381, 'CQ800587', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ800587\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given a try statement, if both the catch block and the finally block each throw an\\nexception, what does the caller see?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The exception from the catch block\"\r\n  }, {\r\n    \"respoonse\" : \"The exception from the finally block\"\r\n  }, {\r\n    \"respoonse\" : \"Both the exception from the catch block and the exception from the finally block\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(382, 'CQ800508', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800508\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package zoo;\\nclass BigCat {\\n\\tvoid roar(int level) throw RuntimeException { // m1\\n\\t\\tif(level<3) throw new IllegalArgumentException(\\\"Incomplete\\\");\\n\\t\\tSystem.out.print(\\\"Roar!\\\");\\n\\t}\\n}\\npublic class Lion extends BigCat {\\n\\tpublic void roar() { // m2\\n\\t\\tSystem.out.print(\\\"Roar!!!\\\");\\n\\t}\\n\\tpublic static void main(String[] cubs) {\\n\\t\\tfinal BigCat kitty = new Lion(); // m3\\n\\t\\tkitty.roar(2);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile because of line m1.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line m2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line m3.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but a stack trace is printed at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(383, 'CQ800836', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800836\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given the following code snippet, which specific exception will be thrown?\",\r\n    \"code\" : \"final Object exception = new Exception();\\nfinal Exception data = (RuntimeException)exception;\\nSystem.out.print(data);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"ClassCastException\"\r\n  }, {\r\n    \"respoonse\" : \"RuntimeException\"\r\n  }, {\r\n    \"respoonse\" : \"NullPointerException\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
