(385, 'CQ800772', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800772\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"In the following application, the values of street and city have been omitted. Which one\\nof the following is a possible output of executing this class?\\nI. 350 5th Ave - New York\\nII. Posted:350 5th Ave - New York\",\r\n    \"code\" : \"package registration;\\npublic class Address {\\n\\tpublic String getAddress(String street, String city) {\\n\\t\\ttry {\\n\\t\\t\\treturn street.toString() + \\\" : \\\" + city.toString();\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(\\\"Posted:\\\");\\n\\t\\t}\\n\\t}\\n\\tpublic static void main(String[] form) {\\n\\t\\tString street = // value omitted\\n\\t\\tString city = // value omitted\\n\\t\\tSystem.out.print(new Address().getAddress(street,city));\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I only\"\r\n  }, {\r\n    \"respoonse\" : \"II only\"\r\n  }, {\r\n    \"respoonse\" : \"I and II\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(386, 'CQ800941', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ800941\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  }, {\r\n    \"id\" : \"85\",\r\n    \"name\" : \"Recognize common exception classes (such as NullPointerException, ArithmeticException, ArrayIndexOutOfBoundsException, ClassCastException)\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"If a try statement has catch blocks for both ClassCastException and RuntimeException,\\nthen which of the following statements is correct?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The catch block for ClassCastException must appear before the catch block for RuntimeException.\"\r\n  }, {\r\n    \"respoonse\" : \"The catch block for RuntimeException must appear before the catch block for ClassCastException.\"\r\n  }, {\r\n    \"respoonse\" : \"The catch blocks for these two exception types can be declared in any order.\"\r\n  }, {\r\n    \"respoonse\" : \"A try statement cannot be declared with these two catch block types because they are incompatible.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
