(394, 'CQ800892', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800892\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of compiling and running the following application?\",\r\n    \"code\" : \"package castles;\\nclass DragonException extends Exception {}\\npublic class Lair {\\n\\tpublic void openDrawbridge() throws Exception { // r1\\n\\t\\ttry {\\n\\t\\t\\tthrow new Exception(\\\"This Exception\\\");\\n\\t\\t} catch (RuntimeException e) {\\n\\t\\t\\tthrow new DragonException(); // r2\\n\\t\\t} finally {\\n\\t\\t\\tthrow new RuntimeException(\\\"Or maybe this one\\\");\\n\\t\\t}\\n\\t}\\n\\tpublic static void main(String[] moat) throws Exception {\\n\\t\\tnew Lair().openDrawbridge(); // r3\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"The code does not compile because of line r1.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line r2.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because of line r3.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles, but a stack trace is printed at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
