(396, 'CQ800143', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800143\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"81\",\r\n    \"name\" : \"Differentiate among checked exceptions, unchecked exceptions, and Errors\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package broken;\\nclass Problem implements RuntimeException {}\\npublic class BiggerProblem extends Problem {\\n\\tpublic static void main(String uhOh[]) {\\n\\t\\ttry {\\n\\t\\t\\tthrow new BiggerProblem();\\n\\t\\t} catch (BiggerProblem re) {\\n\\t\\t\\tSystem.out.print(\\\"Problem?\\\");\\n\\t\\t} catch (Problem e) {\\n\\t\\t\\tSystem.out.print(\\\"Handled\\\");\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(\\\"Fixed!\\\");\\n\\t\\t}\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Problem?Fixed!\"\r\n  }, {\r\n    \"respoonse\" : \"Handled.Fixed!\"\r\n  }, {\r\n    \"respoonse\" : \"Problem?Handled.Fixed!\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(397, 'CQ800602', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800602\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"81\",\r\n    \"name\" : \"Differentiate among checked exceptions, unchecked exceptions, and Errors\"\r\n  }, {\r\n    \"id\" : \"82\",\r\n    \"name\" : \"Create a try-catch block and determine how exceptions alter normal program flow\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following application?\",\r\n    \"code\" : \"package lighting;\\ninterface Source {\\n\\tvoid flipSwitch() throws Exception;\\n}\\npublic class LightBulb implements Source {\\n\\tpublic void flipSwitch() {\\n\\t\\ttry {\\n\\t\\t\\tthrows new RuntimeException(\\\"Circuit Break!\\\");\\n\\t\\t} finally {\\n\\t\\t\\tSystem.out.print(\\\"Flipped!\\\");\\n\\t\\t}\\n\\t}\\n\\tpublic static void main(String... electricity) throws Throwable {\\n\\t\\tfinal Source bulb = new LightBulb();\\n\\t\\tbulb.flipSwitch();\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"A stack trace for a RuntimeException\"\r\n  }, {\r\n    \"respoonse\" : \"Flipped!, followed by a stack trace for a RuntimeException\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile because flipSwitch() is an invalid method override.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile for another reason.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(398, 'CQ800500', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ800500\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"8\",\r\n    \"name\" : \"Handling Exceptions\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"83\",\r\n    \"name\" : \"Describe the advantages of Exception handling\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Given an application that hosts a website, which of the following would most likely result\\nin a java.lang.Error being thrown?\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Two users try to register an account at the same time.\"\r\n  }, {\r\n    \"respoonse\" : \"The application temporarily loses connection to the network.\"\r\n  }, {\r\n    \"respoonse\" : \"A user enters their password incorrectly.\"\r\n  }, {\r\n    \"respoonse\" : \"The application runs out of memory.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
