(411, 'CQ900900', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ900900\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"91\",\r\n    \"name\" : \"Manipulate data using the StringBuilder class and its methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"5: StringBuilder line = new StringBuilder(\\\"-\\\");\\n6: StringBuilder anotherLine = line.append(\\\"-\\\");\\n7: System.out.print(line == anotherLine);\\n8: System.out.print(\\\" \\\");\\n9: System.out.print(line.length());\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"false 1\"\r\n  }, {\r\n    \"respoonse\" : \"false 2\"\r\n  }, {\r\n    \"respoonse\" : \"true 1\"\r\n  }, {\r\n    \"respoonse\" : \"true 2\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(412, 'CQ900590', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ900590\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"91\",\r\n    \"name\" : \"Manipulate data using the StringBuilder class and its methods\"\r\n  }, {\r\n    \"id\" : \"94\",\r\n    \"name\" : \"Declare and use an ArrayList of a given type\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"The author of this method forgot to include the data type. Which of the following reference\\ntypes can fill in the blank to complete this method?\",\r\n    \"code\" : \"public static void secret( mystery) {\\n\\tmystery.add(\\\"metal\\\");\\n\\tString str = mystery.get(0);\\n\\tint num = mystery.length();\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"ArrayList\"\r\n  }, {\r\n    \"respoonse\" : \"ArrayList<String>\"\r\n  }, {\r\n    \"respoonse\" : \"StringBuilder\"\r\n  }, {\r\n    \"respoonse\" : \"None of the above\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(413, 'CQ900183', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ900183\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"91\",\r\n    \"name\" : \"Manipulate data using the StringBuilder class and its methods\"\r\n  }, {\r\n    \"id\" : \"95\",\r\n    \"name\" : \"Write a simple Lambda expression that consumes a Lambda Predicate expression\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which portion of code can be removed so that this line of code continues to compile?\\nPredicate<StringBuilder> p = (StringBuilder b) -> {return true;};\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"Remove StringBuilder b\"\r\n  }, {\r\n    \"respoonse\" : \"Remove ->\"\r\n  }, {\r\n    \"respoonse\" : \"Remove { and ;}\"\r\n  }, {\r\n    \"respoonse\" : \"Remove { return and ;}\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(414, 'CQ900159', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ900159\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"94\",\r\n    \"name\" : \"Declare and use an ArrayList of a given type\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"20: List<Character> chars = new ArrayList<>();\\n21: chars.add(\'a\');\\n22: chars.add(\'b\');\\n23: chars.set(1, \'c\');\\n24: chars.remove(0);\\n25: System.out.print(chars.size() + \\\" \\\" + chars.contains(\'b\'));\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"1 false\"\r\n  }, {\r\n    \"respoonse\" : \"1 true\"\r\n  }, {\r\n    \"respoonse\" : \"2 false\"\r\n  }, {\r\n    \"respoonse\" : \"2 true\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(415, 'CQ900730', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ900730\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"92\",\r\n    \"name\" : \"Create and manipulate Strings\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"12: String b = \\\"12\\\";\\n13: b += \\\"3\\\";\\n14: b.reverse();\\n15: System.out.println(b.toString());\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"12\"\r\n  }, {\r\n    \"respoonse\" : \"123\"\r\n  }, {\r\n    \"respoonse\" : \"321\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(416, 'CQ900756', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ900756\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"92\",\r\n    \"name\" : \"Create and manipulate Strings\"\r\n  }, {\r\n    \"id\" : \"95\",\r\n    \"name\" : \"Write a simple Lambda expression that consumes a Lambda Predicate expression\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many of these lines fail to compile?\",\r\n    \"code\" : \"Predicate<String> pred1 = s -> false;\\nPredicate<String> pred2 = (s) -> false;\\nPredicate<String> pred3 = String s -> false;\\nPredicate<String> pred4 = (String s) -> false;\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"Two\"\r\n  }, {\r\n    \"respoonse\" : \"Three\"\r\n  }, {\r\n    \"respoonse\" : \"Four\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(417, 'CQ900298', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ900298\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"95\",\r\n    \"name\" : \"Write a simple Lambda expression that consumes a Lambda Predicate expression\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What does the following do?\",\r\n    \"code\" : \"public class Shoot {\\n\\tinterface Target {\\n\\t\\tboolean needToAim(double angle);\\n\\t}\\n\\tstatic void prepare(double angle, Target t) {\\n\\t\\tboolean ready = t.needToAim(angle); // k1\\n\\t\\tSystem.out.println(ready);\\n\\t}\\n\\tpublic static void main(String[] args) {\\n\\t\\tprepare(45, d -> d > 5 || d < -5); // k2\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"It prints true.\"\r\n  }, {\r\n    \"respoonse\" : \"It prints false.\"\r\n  }, {\r\n    \"respoonse\" : \"It doesn’t compile due to line k1.\"\r\n  }, {\r\n    \"respoonse\" : \"It doesn’t compile due to line k2.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(418, 'CQ900663', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ900663\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"92\",\r\n    \"name\" : \"Create and manipulate Strings\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"String teams = new String(\\\"694\\\");\\nteams.concat(\\\" 1155\\\");\\nteams.concat(\\\" 2265\\\");\\nteams.concat(\\\" 2869\\\");\\nSystem.out.println(teams);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"694\"\r\n  }, {\r\n    \"respoonse\" : \"694 1155 2265 2869\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but outputs something else.\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java');
