(419, 'CQ900944', '{\r\n  \"format\" : \"TEXT_UP\",\r\n  \"type\" : \"SOFTQUESTION\",\r\n  \"id\" : \"CQ900944\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"92\",\r\n    \"name\" : \"Create and manipulate Strings\"\r\n  }, {\r\n    \"id\" : \"93\",\r\n    \"name\" : \"Create and manipulate calendar data using classes from java.time.LocalDateTime, java.time.LocalDate, java.time.LocalTime, java.time.format.DateTimeFormatter, java.time.Period\"\r\n  }, {\r\n    \"id\" : \"94\",\r\n    \"name\" : \"Declare and use an ArrayList of a given type\"\r\n  } ],\r\n  \"estimateSeconds\" : 60,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of these classes are in the java.util package?\\nI. ArrayList\\nII. LocalDate\\nIII. String\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"I only\"\r\n  }, {\r\n    \"respoonse\" : \"II only\"\r\n  }, {\r\n    \"respoonse\" : \"I and II\"\r\n  }, {\r\n    \"respoonse\" : \"I, II, and III\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'SOFTQUESTION', 1, 'Java'),
(420, 'CQ900965', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ900965\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"91\",\r\n    \"name\" : \"Manipulate data using the StringBuilder class and its methods\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"Which of the answer choices results in a different value being output than the other three\\nchoices?\",\r\n    \"code\" : \"StringBuilder sb = new StringBuilder(\\\"radical \\\");\\nsb = __________________________ ;\\nSystem.out.print(sb);\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"new StringBuilder(\\\"radical \\\") .append(\\\"robots\\\")\"\r\n  }, {\r\n    \"respoonse\" : \"new StringBuilder(\\\"radical \\\") .delete(1, 100) .append(\\\"obots\\\") .insert(1, \\\"adical r\\\")\"\r\n  }, {\r\n    \"respoonse\" : \"new StringBuilder(\\\"radical \\\") .insert(7, \\\"robots\\\")\"\r\n  }, {\r\n    \"respoonse\" : \"new StringBuilder(\\\"radical \\\") .insert(sb.length(), \\\"robots\\\")\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
