(447, 'CQ900617', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ900617\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"92\",\r\n    \"name\" : \"Create and manipulate Strings\"\r\n  }, {\r\n    \"id\" : \"94\",\r\n    \"name\" : \"Declare and use an ArrayList of a given type\"\r\n  }, {\r\n    \"id\" : \"95\",\r\n    \"name\" : \"Write a simple Lambda expression that consumes a Lambda Predicate expression\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"How many lines does this code output?\",\r\n    \"code\" : \"import java.util.*;\\nimport java.util.function.*;\\n\\npublic class PrintNegative {\\n\\tpublic static void main(String[] args) {\\n\\t\\tList<String> list = new ArrayList<>();\\n\\t\\tlist.add(\\\"-5\\\");\\n\\t\\tlist.add(\\\"0\\\");\\n\\t\\tlist.add(\\\"5\\\");\\n\\t\\tprint(list, e -> e < 0);\\n\\t}\\n\\tpublic static void print(List<String> list, Predicate<Integer> p) {\\n\\t\\tfor (String num : list)\\n\\t\\t\\tif (p.test(num))\\n\\t\\t\\t\\tSystem.out.println(num);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"One\"\r\n  }, {\r\n    \"respoonse\" : \"two\"\r\n  }, {\r\n    \"respoonse\" : \"None. The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"None. The code throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(448, 'CQ900881', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"HARDQUESTION\",\r\n  \"id\" : \"CQ900881\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"92\",\r\n    \"name\" : \"Create and manipulate Strings\"\r\n  } ],\r\n  \"estimateSeconds\" : 150,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"12: List<String> magazines = new ArrayList();\\n13: magazines.add(\\\"Readers Digest\\\");\\n14: magazines.add(\\\"People\\\");\\n15: magazines.clear();\\n16: magazines.add(\\\"The Economist\\\");\\n17: magazines.remove(1);\\n18: System.out.println(magazines.size());\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"0\"\r\n  }, {\r\n    \"respoonse\" : \"1\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'HARDQUESTION', 1, 'Java'),
(449, 'CQ900669', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ900669\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"92\",\r\n    \"name\" : \"Create and manipulate Strings\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the output of the following?\",\r\n    \"code\" : \"public class Costume {\\n\\tpublic static void main(String[] black) {\\n\\t\\tString witch = \'b\';\\n\\t\\tString tail = \\\"lack\\\";\\n\\t\\twitch = witch.concat(tail);\\n\\t\\tSystem.out.println(witch);\\n\\t}\\n}\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"b\"\r\n  }, {\r\n    \"respoonse\" : \"black\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java'),
(450, 'CQ900475', '{\r\n  \"format\" : \"TEXT_UP_COD\",\r\n  \"type\" : \"MIDLELEVELQUESTION\",\r\n  \"id\" : \"CQ900475\",\r\n  \"mainObjectives\" : [ {\r\n    \"id\" : \"9\",\r\n    \"name\" : \"Working with Selected classes from the Java API\"\r\n  } ],\r\n  \"secondaryObjectives\" : [ {\r\n    \"id\" : \"93\",\r\n    \"name\" : \"Create and manipulate calendar data using classes from java.time.LocalDateTime, java.time.LocalDate, java.time.LocalTime, java.time.format.DateTimeFormatter, java.time.Period\"\r\n  } ],\r\n  \"estimateSeconds\" : 100,\r\n  \"Content\" : {\r\n    \"textUP\" : \"What is the result of the following?\",\r\n    \"code\" : \"LocalDate xmas = LocalDate.of(2016, 12, 25);\\nxmas.setYear(2017);\\nSystem.out.println(xmas.getYear());\"\r\n  },\r\n  \"responses\" : [ {\r\n    \"respoonse\" : \"2016\"\r\n  }, {\r\n    \"respoonse\" : \"2017\"\r\n  }, {\r\n    \"respoonse\" : \"The code does not compile.\"\r\n  }, {\r\n    \"respoonse\" : \"The code compiles but throws an exception at runtime.\"\r\n  } ],\r\n  \"answers\" : [ {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : false\r\n  }, {\r\n    \"answer\" : true\r\n  }, {\r\n    \"answer\" : false\r\n  } ],\r\n  \"hint\" : \"No\",\r\n  \"partialScore\" : true,\r\n  \"domain\" : \"Java\"\r\n}', 'MIDLELEVELQUESTION', 1, 'Java');
